//! `cdda-read-contention` -- a focused PS1 CD-ROM conformance probe.
//!
//! It reproduces the exact situation cortex_ignition_v1 hits on real
//! hardware: menu CD-DA is playing, then gameplay issues a data read
//! WITHOUT pausing/stopping the drive first. The guest's `cd_stream`
//! reports `STATUS_CD_ERROR` there, which is an INT5 (Error) IRQ.
//!
//! This program drives the controller through the engine's real read
//! path and records WHICH IRQ the ReadN produces, so the same binary can
//! be compared across PSoXide, PCSX-Redux, DuckStation, and a console.
//!
//! Sequence (matches `engine/.../cd_stream/hw.rs`):
//!   SetMode CDDA|2x -> Demute -> Play(track 2)        [CD-DA, PLAYING]
//!   SetMode 2x (drop CDDA) -> SetLoc(data LBA) -> ReadN    [contention]
//!
//! Result is written to uncached RAM at `RESULT_BASE` (so an emulator
//! peek or a hardware probe sees it without cache games) and printed to
//! TTY. `RESULT_BASE+0` is the completion magic, written last.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_io::{read_u8, write_u32, write_u8};
use psx_rt::tty;

use psx_hw::cd::index_status::{
    DATA_FIFO_NOT_EMPTY as STAT_DATA_NOT_EMPTY, RESPONSE_NOT_EMPTY as STAT_RESP_NOT_EMPTY,
};
use psx_hw::cd::irq::{DATA_READY as IRQ_DATA_READY, ERROR as IRQ_ERROR};
use psx_hw::cd::reg::{
    COMMAND_RESPONSE as CD_CMD, INDEX as CD_STATUS, PARAMETER as CD_PARAM, REQUEST_IRQ as CD_IRQ,
};

// Uncached (KSEG1) RAM mirror so writes land in RAM immediately.
const RESULT_BASE: u32 = 0xa010_0000;
const DONE_MAGIC: u32 = 0x0c0d_0001;

const PLAY_TRACK: u8 = 2;
const DATA_LBA: u32 = 16;
const POLL_LIMIT: u32 = 4_000_000;

static SPIN_SINK: u32 = 0;

struct Resp {
    irq: u8,
    stat: u8,
}

#[no_mangle]
fn main() {
    unsafe {
        run();
    }
    loop {
        core::hint::spin_loop();
    }
}

unsafe fn run() {
    // Mask CDROM at the CPU IRQ controller and poll the controller flag
    // directly, exactly like the engine's polled read path.
    psx_io::irq::set_mask(1 << psx_hw::irq::source::VBLANK);
    cd_set_index(1);
    write_u8(CD_PARAM, 0x00); // controller IRQ enable = 0 (poll only)
    write_u8(CD_IRQ, 0x1f); // ack any pending
    cd_set_index(0);

    write_result(0x14, 1);

    // 1) Menu-style CD-DA playback.
    let _ = cd_command(0x0e, &[0x81]); // SetMode: CDDA | DOUBLE_SPEED
    let _ = cd_command(0x0c, &[]); // Demute
    let _ = cd_command(0x03, &[bcd(PLAY_TRACK)]); // Play track 2

    // Let the drive settle into playback, then sample the stat byte.
    spin(2_000_000);
    let play = cd_command(0x01, &[]); // GetStat
    write_result(0x08, play.stat as u32);
    write_result(0x14, 2);

    // 2) Engine read path WHILE CD-DA plays, with no Pause/Stop first.
    let _ = cd_command(0x0e, &[0x80]); // SetMode: DOUBLE_SPEED only (drop CDDA)
    let (m, s, f) = lba_to_bcd_msf(DATA_LBA);
    let _ = cd_command(0x02, &[m, s, f]); // SetLoc(data sector)
    write_result(0x14, 3);

    // Issue ReadN and capture EVERY IRQ it produces.
    cd_ack_all();
    cd_set_index(0);
    drain_responses();
    write_u8(CD_CMD, 0x06); // ReadN

    let mut irq_seen = 0u32;
    let mut last_stat = 0u8;
    let mut data_ready = 0u32;
    let mut polls = 0;
    while polls < 6 {
        let flag = poll_irq(POLL_LIMIT);
        if flag == 0 {
            break;
        }
        irq_seen |= 1u32 << (flag & 0x7);
        last_stat = read_first_response();
        if cd_status() & STAT_DATA_NOT_EMPTY != 0 {
            data_ready = 1;
        }
        cd_ack(flag);
        // A data-ready or an error settles the question.
        if flag == IRQ_DATA_READY || flag == IRQ_ERROR {
            break;
        }
        polls += 1;
    }
    if cd_status() & STAT_DATA_NOT_EMPTY != 0 {
        data_ready = 1;
    }

    write_result(0x04, irq_seen);
    write_result(0x0c, last_stat as u32);
    write_result(0x10, data_ready);
    write_result(0x14, 4);

    // Human/harness-readable summary.
    tty::print("CDDA-CONTENTION irq=0x");
    tty::print_hex_u32(irq_seen);
    tty::print(" play_stat=0x");
    tty::print_hex_u32(play.stat as u32);
    tty::print(" read_stat=0x");
    tty::print_hex_u32(last_stat as u32);
    tty::print(" data=0x");
    tty::print_hex_u32(data_ready);
    if irq_seen & (1 << IRQ_ERROR) != 0 {
        tty::println(" RESULT=INT5_ERROR");
    } else if irq_seen & (1 << IRQ_DATA_READY) != 0 {
        tty::println(" RESULT=DATA_DELIVERED");
    } else {
        tty::println(" RESULT=UNKNOWN");
    }

    // Completion marker LAST so a reader can poll RESULT_BASE+0.
    write_result(0x00, DONE_MAGIC);
}

unsafe fn cd_command(cmd: u8, params: &[u8]) -> Resp {
    cd_ack_all();
    cd_set_index(0);
    drain_responses();
    for &p in params {
        write_u8(CD_PARAM, p);
    }
    write_u8(CD_CMD, cmd);
    let irq = poll_irq(POLL_LIMIT); // INT3 ack, or INT5 error
    let stat = read_first_response();
    cd_ack(irq);
    Resp { irq, stat }
}

unsafe fn poll_irq(limit: u32) -> u8 {
    let mut i = 0u32;
    loop {
        cd_set_index(1);
        let flag = read_u8(CD_IRQ) & 0x1f;
        cd_set_index(0);
        if flag != 0 {
            return flag;
        }
        if i >= limit {
            return 0;
        }
        i += 1;
    }
}

unsafe fn read_first_response() -> u8 {
    cd_set_index(0);
    let mut first = 0u8;
    let mut got = false;
    while cd_status() & STAT_RESP_NOT_EMPTY != 0 {
        let b = read_u8(CD_CMD);
        if !got {
            first = b;
            got = true;
        }
    }
    first
}

unsafe fn drain_responses() {
    let _ = read_first_response();
}

unsafe fn cd_ack(bits: u8) {
    cd_set_index(1);
    write_u8(CD_IRQ, bits & 0x1f);
    cd_set_index(0);
}

unsafe fn cd_ack_all() {
    cd_ack(0x1f);
}

unsafe fn cd_status() -> u8 {
    read_u8(CD_STATUS)
}

unsafe fn cd_set_index(index: u8) {
    write_u8(CD_STATUS, index & 0x03);
}

unsafe fn write_result(offset: u32, value: u32) {
    write_u32(RESULT_BASE + offset, value);
}

fn bcd(v: u8) -> u8 {
    ((v / 10) << 4) | (v % 10)
}

fn lba_to_bcd_msf(lba: u32) -> (u8, u8, u8) {
    let total = lba + 150;
    let m = (total / (75 * 60)) as u8;
    let s = ((total / 75) % 60) as u8;
    let f = (total % 75) as u8;
    (bcd(m), bcd(s), bcd(f))
}

fn spin(n: u32) {
    let mut i = 0u32;
    while i < n {
        unsafe {
            core::ptr::read_volatile(&SPIN_SINK);
        }
        i += 1;
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! One-plane lane clip: the portable definition against the kernel.

use crate::{print_dec, Rng};
use core::hint::black_box;
use psx_math::clip_lanes::{clip_lanes8_plane, clip_lanes8_plane_reference, LanePlane, Lanes8};

/// GoldSrc-shaped planes for a 320x240 view with projection distance `h`.
fn view_planes(h: i32, capacity: u32) -> [LanePlane; 5] {
    let (ofx, ofy, vx0, vx1, vy0, vy1) = (160, 120, 0, 320, 0, 240);
    let plane = |primary_offset, primary, depth, bias, force| LanePlane {
        primary_offset,
        primary,
        depth,
        bias,
        force_depth: force,
        forced_depth: 8,
        capacity,
    };
    [
        plane(0, 0, 1, -8, 1),         // near: z - 8, crossing lands on z = 8
        plane(0, h, ofx - vx0, 0, 0),  // left
        plane(0, -h, vx1 - ofx, 0, 0), // right
        plane(4, h, ofy - vy0, 0, 0),  // top
        plane(4, -h, vy1 - ofy, 0, 0), // bottom
    ]
}

fn make_vertex(rng: &mut Rng, mode: u32) -> Lanes8 {
    let r = rng.next();
    let s = rng.next();
    let t = rng.next();
    match mode {
        0 => [
            ((r & 0x1fff) as i32) - 4096,
            (((r >> 13) & 0x1fff) as i32) - 4096,
            ((s & 0x3fff) as i32) - 2000,
            (t & 0xff) as i32,
            ((t >> 8) & 0xff) as i32,
            ((t >> 16) & 0xff) as i32,
            (s >> 14 & 0xff) as i32,
            (s >> 22 & 0xff) as i32,
        ],
        // The whole i32 range on every lane: products and differences wrap.
        1 => [
            r as i32,
            s as i32,
            t as i32,
            rng.next() as i32,
            rng.next() as i32,
            rng.next() as i32,
            rng.next() as i32,
            rng.next() as i32,
        ],
        // Small coordinates and a z around the near plane, so distances hit 0
        // and equal x or y make the endpoint order fall through to later lanes.
        2 => [
            (r & 3) as i32 - 1,
            ((r >> 2) & 3) as i32 - 1,
            4 + ((s & 7) as i32),
            (t & 0xff) as i32,
            ((t >> 8) & 0xff) as i32,
            ((t >> 16) & 0xff) as i32,
            (s >> 8 & 0xff) as i32,
            (s >> 16 & 0xff) as i32,
        ],
        // Extremes.
        _ => {
            let pick = |v: u32| match v % 5 {
                0 => i32::MIN,
                1 => i32::MAX,
                2 => 0,
                3 => -1,
                _ => 1,
            };
            [
                pick(r),
                pick(r >> 4),
                pick(r >> 8),
                pick(s),
                pick(s >> 4),
                pick(s >> 8),
                pick(t),
                pick(t >> 4),
            ]
        }
    }
}

static mut SRC: [Lanes8; 8] = [[0; 8]; 8];
static mut DST_REF: [Lanes8; 9] = [[0; 8]; 9];
static mut DST_TST: [Lanes8; 9] = [[0; 8]; 9];

pub fn run(cases: &mut u32, failures: &mut u32) {
    let mut rng = Rng(0x1357_9bdf);
    unsafe {
        let src = core::ptr::addr_of_mut!(SRC) as *mut Lanes8;
        let dref = core::ptr::addr_of_mut!(DST_REF) as *mut Lanes8;
        let dtst = core::ptr::addr_of_mut!(DST_TST) as *mut Lanes8;
        for mode in 0..4u32 {
            for iteration in 0..400u32 {
                let h = [256, 320, 1, 4096, -7][(iteration % 5) as usize];
                let capacity = if iteration % 7 == 0 {
                    2 + (iteration / 7) % 7
                } else {
                    8
                };
                let planes = view_planes(h, capacity);
                let n = (rng.next() % 9) as usize; // 0..=8
                for i in 0..n {
                    *src.add(i) = make_vertex(&mut rng, mode);
                }
                if iteration % 11 == 0 && n > 2 {
                    // Duplicate vertices: equal endpoints, d_a == d_b.
                    *src.add(1) = *src;
                }
                let plane = &planes[(iteration % 5) as usize];
                // Poison both destinations identically, including the spare slot.
                for i in 0..9 {
                    *dref.add(i) = [0x5a5a_5a5au32 as i32; 8];
                    *dtst.add(i) = [0x5a5a_5a5au32 as i32; 8];
                }
                *cases += 1;
                let a = clip_lanes8_plane_reference(src, n, dref, plane);
                let b = clip_lanes8_plane(src, n, dtst, plane);
                let mut same = a == b;
                for i in 0..9 {
                    if (*dref.add(i)) != (*dtst.add(i)) {
                        same = false;
                    }
                }
                if !same {
                    *failures += 1;
                    if *failures < 6 {
                        crate::tty_fail("clip", mode, iteration, (a as u32) << 8 | b as u32);
                    }
                }
            }
        }
    }
}

/// Representative HL polygons: triangles with one or two vertices outside the
/// plane, the way the view clip sees them, cycled across the five planes.
pub fn bench() {
    let mut rng = Rng(0x2468_ace1);
    unsafe {
        let src = core::ptr::addr_of_mut!(SRC) as *mut Lanes8;
        let dst = core::ptr::addr_of_mut!(DST_TST) as *mut Lanes8;
        let planes = view_planes(256, 8);
        let mut total_ref = 0u32;
        let mut total_k = 0u32;
        let mut over = 0u32;
        let mut calls = 0u32;
        for iteration in 0..200u32 {
            // A triangle across the near plane or one side plane: vertices
            // straddle by construction.
            let plane = &planes[(iteration % 5) as usize];
            let n = 3 + (iteration % 3) as usize; // triangles, quads, pentagons
            for i in 0..n {
                let mut v = make_vertex(&mut rng, 0);
                v[2] = v[2].abs() + 8 + (i as i32 * 700);
                // Push alternate vertices to the far side of the plane.
                if i % 2 == 0 {
                    match iteration % 5 {
                        0 => v[2] = 2 + (v[2] & 3),
                        1 => v[0] = -(v[2] + 100),
                        2 => v[0] = v[2] + 100,
                        3 => v[1] = -(v[2] + 100),
                        _ => v[1] = v[2] + 100,
                    }
                }
                *src.add(i) = v;
            }
            let a = crate::clock();
            let b = crate::clock();
            over += b.wrapping_sub(a) as u32;
            let a = crate::clock();
            let nr = black_box(clip_lanes8_plane_reference)(src, n, dst, plane);
            let b = crate::clock();
            total_ref += b.wrapping_sub(a) as u32;
            let a = crate::clock();
            let nk = black_box(clip_lanes8_plane)(src, n, dst, plane);
            let b = crate::clock();
            total_k += b.wrapping_sub(a) as u32;
            black_box((nr, nk));
            calls += 1;
        }
        crate::tty_label_clip("reference");
        print_dec("", (total_ref - over) * 10 / calls);
        crate::tty_label_clip("kernel");
        print_dec("", (total_k - over) * 10 / calls);
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! Tagged-packet-stream link loop: the portable reference, the inline-asm loop
//! the SDK uses by default, and the `asm-kernels` kernel.

use crate::{print_dec, print_u32, Rng};
use core::arch::global_asm;
use core::hint::black_box;

pub const OT_N: usize = 2048;
const OT_END: u32 = 0x00ff_ffff;
const MASK: u32 = 0x00ff_ffff;
const ARENA_WORDS: usize = 1 << 16;

#[repr(C, align(4))]
pub struct Ot(pub [u32; OT_N]);

static mut OT_REF: Ot = Ot([0; OT_N]);
static mut OT_TST: Ot = Ot([0; OT_N]);
static mut ARENA_REF: [u32; ARENA_WORDS + 64] = [0; ARENA_WORDS + 64];
static mut ARENA_TST: [u32; ARENA_WORDS + 64] = [0; ARENA_WORDS + 64];
static mut ARENA_SRC: [u32; ARENA_WORDS + 64] = [0; ARENA_WORDS + 64];

pub fn ot_clear(ot: &mut Ot) {
    let base = ot.0.as_ptr() as u32;
    ot.0[0] = OT_END;
    for i in 1..OT_N {
        ot.0[i] = base.wrapping_add(4 * (i as u32 - 1)) & MASK;
    }
}

/// The portable definition, line for line the host branch of
/// `OrderingTable::link_tagged_packet_stream_unchecked`.
pub unsafe fn link_ref(entries: *mut u32, first: *mut u32, end: *mut u32) {
    let mut p = first;
    while p < end {
        let tag = p.read();
        let words = (tag >> 24) as usize;
        let slot = (tag & 0xffff) as usize;
        let next = p.add(words + 1);
        if slot != 0xffff {
            let head = entries.add(slot).read() & MASK;
            p.write((tag & 0xff00_0000) | head);
            entries.add(slot).write(p as u32 & MASK);
        }
        p = next;
    }
}

extern "C" {
    fn asmprobe_link_cur(first: *mut u32, end: *mut u32, entries: *mut u32);
}

// The inline-asm loop `ot.rs` uses without the `asm-kernels` feature, as a leaf
// function: the baseline the kernel is timed against.
global_asm!(
    r#"
    .set noreorder
    .set nomacro
    .section .text.asmprobe_link,"ax",@progbits
    .globl asmprobe_link_cur
    .type asmprobe_link_cur,@function
asmprobe_link_cur:
    nop
    sltu   $t0, $a0, $a1
    beqz   $t0, 9f
    nop
    lui    $t7, 0x00ff
    ori    $t7, $t7, 0xffff
    ori    $t9, $zero, 0xffff
    lui    $t8, 0xff00
2:
    lw     $t1, 0($a0)
    and    $t3, $a0, $t7
    srl    $t2, $t1, 22
    andi   $t5, $t1, 0xffff
    addu   $t2, $a0, $t2
    beq    $t5, $t9, 3f
    addiu  $t2, $t2, 4
    sll    $t5, $t5, 2
    addu   $t5, $a2, $t5
    lw     $t6, 0($t5)
    and    $t1, $t1, $t8
    or     $t6, $t6, $t1
    sw     $t6, 0($a0)
    sw     $t3, 0($t5)
3:
    bne    $t2, $a1, 2b
    move   $a0, $t2
9:
    jr     $ra
    nop
    .size asmprobe_link_cur, .-asmprobe_link_cur
"#
);

/// A deliberately wrong kernel for the harness self-check: it forgets the
/// sentinel and links skipped packets into slot 0xffff & mask.
unsafe extern "C" fn mutant_link(first: *mut u32, end: *mut u32, entries: *mut u32) {
    let mut p = first;
    while p < end {
        let tag = p.read();
        let words = (tag >> 24) as usize;
        let slot = (tag & 0xffff) as usize & (OT_N - 1);
        let next = p.add(words + 1);
        let head = entries.add(slot).read() & MASK;
        p.write((tag & 0xff00_0000) | head);
        entries.add(slot).write(p as u32 & MASK);
        p = next;
    }
}

/// The SDK's own entry point (`asm-kernels` selects the kernel under test).
unsafe extern "C" fn sdk_link(first: *mut u32, end: *mut u32, entries: *mut u32) {
    let ot = &mut *(entries as *mut psx_gpu::ot::OrderingTable<OT_N>);
    let mut frame = ot.resume_frame();
    frame.add_tagged_packet_stream_unchecked(first, end);
}

/// Fill `arena` with a deterministic packet stream and return its end.
/// `mode` selects the slot distribution; every mode keeps bits 16..23 of a tag
/// clear, as the staged format requires.
unsafe fn make_stream(arena: *mut u32, rng: &mut Rng, packets: usize, mode: u32) -> *mut u32 {
    let mut p = arena;
    let mut asc = 0u32;
    for i in 0..packets {
        let r = rng.next();
        let words = match mode {
            7 => 0,
            8 => (r >> 8) % 3, // zero-length mixed with tiny
            12 => 15,
            _ => match r % 16 {
                0..=4 => 4,
                5..=8 => 5 + (r >> 8) % 2,
                9..=12 => 8 + (r >> 8) % 2,
                13 => 1 + (r >> 8) % 3,
                _ => 10 + (r >> 8) % 6,
            },
        };
        let s = rng.next();
        let slot = match mode {
            0 => s % OT_N as u32,
            1 => {
                if s % 5 != 0 {
                    1000 + (s >> 8) % 64
                } else {
                    (s >> 8) % OT_N as u32
                }
            }
            2 => 0,
            3 => OT_N as u32 - 1,
            4 => {
                if s % 20 == 0 {
                    0xffff
                } else {
                    (s >> 4) % OT_N as u32
                }
            }
            5 => {
                asc = (asc + 1 + (s % 3)) % OT_N as u32;
                asc
            }
            6 => (OT_N as u32 - 1) - (i as u32 % OT_N as u32),
            9 => 0xffff,
            10 => {
                if i == 0 || i + 1 == packets {
                    0xffff
                } else {
                    (s >> 4) % OT_N as u32
                }
            }
            11 => {
                if i % 2 == 0 {
                    0xffff
                } else {
                    (s >> 4) % OT_N as u32
                }
            }
            12 => 5,
            _ => (s >> 4) % OT_N as u32,
        };
        p.write((words << 24) | slot);
        for w in 0..words as usize {
            p.add(1 + w).write(rng.next());
        }
        p = p.add(1 + words as usize);
    }
    p
}

unsafe fn run_variant(
    kernel: unsafe extern "C" fn(*mut u32, *mut u32, *mut u32),
    seed: u32,
    packets: usize,
    mode: u32,
) -> u32 {
    let ot_ref = &mut *core::ptr::addr_of_mut!(OT_REF);
    let ot_tst = &mut *core::ptr::addr_of_mut!(OT_TST);
    let src = core::ptr::addr_of_mut!(ARENA_SRC) as *mut u32;
    let arena_ref = core::ptr::addr_of_mut!(ARENA_REF) as *mut u32;
    let arena_tst = core::ptr::addr_of_mut!(ARENA_TST) as *mut u32;
    let mut rng = Rng(seed | 1);
    let end_src = make_stream(src, &mut rng, packets, mode);
    let n = end_src.offset_from(src) as usize;
    core::ptr::copy_nonoverlapping(src, arena_ref, n);
    core::ptr::copy_nonoverlapping(src, arena_tst, n);
    // The table holds addresses of its own entries and of packets, so both runs
    // must see the same addresses: link the reference into the reference arena
    // with the reference table, the candidate into the test arena with the test
    // table, and compare after mapping addresses to offsets.
    ot_clear(ot_ref);
    ot_clear(ot_tst);
    link_ref(ot_ref.0.as_mut_ptr(), arena_ref, arena_ref.add(n));
    kernel(arena_tst, arena_tst.add(n), ot_tst.0.as_mut_ptr());
    let mut bad = 0u32;
    // Entries: packet addresses are offsets from each arena's base.
    let base_ref = arena_ref as u32 & MASK;
    let base_tst = arena_tst as u32 & MASK;
    let tbl_ref = ot_ref.0.as_ptr() as u32 & MASK;
    let tbl_tst = ot_tst.0.as_ptr() as u32 & MASK;
    for i in 0..OT_N {
        let a = ot_ref.0[i];
        let b = ot_tst.0[i];
        let ok = if a >= base_ref && a < base_ref + (n as u32) * 4 {
            b == a - base_ref + base_tst
        } else if a >= tbl_ref && a < tbl_ref + (OT_N as u32) * 4 {
            b == a - tbl_ref + tbl_tst
        } else {
            a == b
        };
        if !ok {
            bad += 1;
        }
    }
    for i in 0..n {
        let a = *arena_ref.add(i);
        let b = *arena_tst.add(i);
        // Link words differ by the base; compare the count byte exactly and the
        // address as an offset. Data words are bit-identical.
        let is_tag = a & 0x00ff_0000 == 0 && false;
        let _ = is_tag;
        if a != b {
            // A tag word holds an address: map it.
            let (ra, rb) = (a & MASK, b & MASK);
            let ok = (a >> 24) == (b >> 24)
                && ((ra >= base_ref
                    && ra < base_ref + (n as u32) * 4
                    && rb == ra - base_ref + base_tst)
                    || (ra >= tbl_ref
                        && ra < tbl_ref + (OT_N as u32) * 4
                        && rb == ra - tbl_ref + tbl_tst)
                    || ra == rb);
            if !ok {
                bad += 1;
            }
        }
    }
    bad
}

pub fn run(cases: &mut u32, failures: &mut u32) {
    // Self-check: the harness must reject a wrong kernel on the sentinel mode.
    let caught = unsafe { run_variant(mutant_link, 4242, 500, 4) };
    *cases += 1;
    if caught == 0 {
        *failures += 1;
        psx_rt::tty::println("  harness failed to catch the mutant");
    }
    let kernels: [(&str, unsafe extern "C" fn(*mut u32, *mut u32, *mut u32)); 2] =
        [("cur", asmprobe_link_cur), ("sdk", sdk_link)];
    for (name, k) in kernels.iter() {
        let mut fails = 0u32;
        psx_rt::tty::print("testing ");
        psx_rt::tty::println(name);
        for mode in 0..13u32 {
            for &packets in &[0usize, 1, 2, 3, 7, 64, 500, 3000] {
                for seed in 1..6u32 {
                    *cases += 1;
                    let bad = unsafe { run_variant(*k, seed * 7919 + mode, packets, mode) };
                    if bad != 0 {
                        fails += 1;
                        *failures += 1;
                        if fails < 4 {
                            crate::tty_fail(name, mode, packets as u32, bad);
                        }
                    }
                }
            }
        }
    }
}

/// Time `kernel` over `reps` fresh streams of `packets` packets; returns
/// (total cycles, total packets). The empty-timer overhead is removed.
unsafe fn time_kernel(
    kernel: unsafe extern "C" fn(*mut u32, *mut u32, *mut u32),
    mode: u32,
    packets: usize,
    reps: u32,
) -> (u32, u32) {
    let ot_tst = &mut *core::ptr::addr_of_mut!(OT_TST);
    let src = core::ptr::addr_of_mut!(ARENA_SRC) as *mut u32;
    let arena_tst = core::ptr::addr_of_mut!(ARENA_TST) as *mut u32;
    let mut rng = Rng(12345 + mode);
    let end_src = make_stream(src, &mut rng, packets, mode);
    let n = end_src.offset_from(src) as usize;
    let mut total = 0u32;
    let mut overhead = 0u32;
    for _ in 0..reps {
        core::ptr::copy_nonoverlapping(src, arena_tst, n);
        ot_clear(ot_tst);
        let a = crate::clock();
        let b = crate::clock();
        overhead += b.wrapping_sub(a) as u32;
        let a = crate::clock();
        black_box(kernel)(arena_tst, arena_tst.add(n), ot_tst.0.as_mut_ptr());
        let b = crate::clock();
        total += b.wrapping_sub(a) as u32;
    }
    (total.saturating_sub(overhead), packets as u32 * reps)
}

pub fn bench() {
    let kernels: [(&str, unsafe extern "C" fn(*mut u32, *mut u32, *mut u32)); 2] =
        [("cur", asmprobe_link_cur), ("sdk", sdk_link)];
    for mode in [0u32, 1, 4] {
        for (name, k) in kernels.iter() {
            let (cycles, packets) = unsafe { time_kernel(*k, mode, 300, 16) };
            crate::tty_label(name, mode);
            // hundredths of a cycle per packet
            print_dec("", cycles * 100 / packets);
        }
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! `hello-asmprobe` -- differential probe and micro-benchmark for the SDK's
//! hand-scheduled kernels.
//!
//! Every kernel is compared bit for bit against a portable Rust reference on
//! random and hand-picked edge inputs, then timed on a fixed workload. The
//! verdict goes to the TTY (`ASMPROBE PASS` / `ASMPROBE FAIL`). Per-function
//! cycles come from the emulator's attribution logs over the link map.

#![no_std]
#![no_main]
#![feature(asm_experimental_arch)]

extern crate psx_rt;

mod clip;
mod link;

use psx_rt::tty;

/// xorshift32, the same stream on every run.
pub struct Rng(pub u32);

impl Rng {
    pub fn next(&mut self) -> u32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.0 = x;
        x
    }
}

pub fn tty_fail(name: &str, mode: u32, packets: u32, bad: u32) {
    tty::print("  FAIL ");
    tty::print(name);
    tty::print(" mode=");
    tty::print_hex_u32(mode);
    tty::print(" packets=");
    tty::print_hex_u32(packets);
    tty::print(" bad=");
    tty::print_hex_u32(bad);
    tty::println("");
}

/// The system clock as a 16-bit counter: root counter 1 on the system clock.
pub fn clock_start() {
    psx_io::timers::set_mode(psx_io::timers::Timer::Timer1, 0);
}

#[inline(always)]
pub fn clock() -> u16 {
    psx_io::timers::counter(psx_io::timers::Timer::Timer1)
}

pub fn print_dec(label: &str, v: u32) {
    tty::print(label);
    let mut buf = [0u8; 10];
    let mut n = 0;
    let mut x = v;
    if x == 0 {
        buf[0] = b'0';
        n = 1;
    }
    while x > 0 {
        buf[n] = b'0' + (x % 10) as u8;
        x /= 10;
        n += 1;
    }
    let mut out = [0u8; 10];
    for i in 0..n {
        out[i] = buf[n - 1 - i];
    }
    tty::print(core::str::from_utf8(&out[..n]).unwrap());
    tty::println("");
}

pub fn tty_label_clip(name: &str) {
    tty::print("BENCH clip ");
    tty::print(name);
    tty::print(" cyc/10call=");
}

pub fn tty_label(name: &str, mode: u32) {
    tty::print("BENCH link ");
    tty::print(name);
    tty::print(" mode=");
    tty::print_hex_u32(mode);
    tty::print(" cyc/100pkt=");
}

pub fn print_u32(label: &str, v: u32) {
    tty::print(label);
    tty::print_hex_u32(v);
    tty::println("");
}

#[no_mangle]
fn main() {
    clock_start();
    let mut failures = 0u32;
    let mut cases = 0u32;
    clip::run(&mut cases, &mut failures);
    clip::bench();
    link::run(&mut cases, &mut failures);
    if failures == 0 {
        tty::print("ASMPROBE PASS cases=");
        tty::print_hex_u32(cases);
        tty::println("");
    } else {
        tty::print("ASMPROBE FAIL ");
        tty::print_hex_u32(failures);
        tty::print(" of ");
        tty::print_hex_u32(cases);
        tty::println("");
    }
    link::bench();
    tty::println("ASMPROBE DONE");
    loop {}
}

