fn make_test_icon() -> SaveIcon {
    let mut palette = [0u16; 16];
    palette[0] = 0x0000; // transparent
    palette[1] = 0x1084; // dark blue-grey fill
    palette[2] = 0x7fe0; // cyan outline
    palette[3] = 0x7fff; // white
    palette[4] = 0x23e8; // green confirmation mark

    let mut pixels = [0u8; FRAME_SIZE];
    let mut y = 1usize;
    while y < 15 {
        let mut x = 2usize;
        while x < 14 {
            let colour = if x == 2 || x == 13 || y == 1 || y == 14 {
                2
            } else {
                1
            };
            set_icon_pixel(&mut pixels, x, y, colour);
            x += 1;
        }
        y += 1;
    }
    // Memory-card label and notch.
    let mut x = 5;
    while x < 11 {
        set_icon_pixel(&mut pixels, x, 3, 3);
        x += 1;
    }
    set_icon_pixel(&mut pixels, 10, 1, 0);
    set_icon_pixel(&mut pixels, 11, 1, 0);
    // A compact check mark.
    set_icon_pixel(&mut pixels, 5, 9, 4);
    set_icon_pixel(&mut pixels, 6, 10, 4);
    set_icon_pixel(&mut pixels, 7, 11, 4);
    set_icon_pixel(&mut pixels, 8, 10, 4);
    set_icon_pixel(&mut pixels, 9, 9, 4);
    set_icon_pixel(&mut pixels, 10, 8, 4);
    set_icon_pixel(&mut pixels, 11, 7, 4);

    SaveIcon::new(palette, pixels)
}

fn set_icon_pixel(pixels: &mut [u8; FRAME_SIZE], x: usize, y: usize, colour: u8) {
    let at = (y * 16 + x) / 2;
    if x & 1 == 0 {
        pixels[at] = (pixels[at] & 0xf0) | (colour & 0x0f);
    } else {
        pixels[at] = (pixels[at] & 0x0f) | ((colour & 0x0f) << 4);
    }
}

fn make_payload(generation: u32) -> [u8; PAYLOAD_LEN] {
    let mut out = [0u8; PAYLOAD_LEN];
    out[..MAGIC.len()].copy_from_slice(MAGIC);
    out[8] = 1;
    out[9..13].copy_from_slice(&generation.to_le_bytes());
    let mut i = 13;
    while i < 60 {
        out[i] = (i as u8)
            .wrapping_mul(37)
            .wrapping_add(generation as u8)
            .rotate_left((generation & 7) as u32);
        i += 1;
    }
    let checksum = hash_bytes(0x811c_9dc5, &out[..60]);
    out[60..64].copy_from_slice(&checksum.to_le_bytes());
    out
}

fn validate_payload(payload: &[u8; PAYLOAD_LEN], len: usize) -> Option<u32> {
    if len != PAYLOAD_LEN || &payload[..8] != MAGIC || payload[8] != 1 {
        return None;
    }
    let generation = u32::from_le_bytes([payload[9], payload[10], payload[11], payload[12]]);
    if make_payload(generation) == *payload {
        Some(generation)
    } else {
        None
    }
}

fn hash_bytes(mut hash: u32, bytes: &[u8]) -> u32 {
    let mut i = 0;
    while i < bytes.len() {
        hash ^= bytes[i] as u32;
        hash = hash.wrapping_mul(0x0100_0193);
        i += 1;
    }
    hash
}

fn error_name(error: Error) -> &'static str {
    match error {
        Error::NoCard => "NO-CARD",
        Error::Protocol => "PROTOCOL",
        Error::BadChecksum => "CHECKSUM",
        Error::OutOfRange => "RANGE",
        Error::NotFormatted => "UNFORMATTED",
        Error::NotFound => "NOT-FOUND",
        Error::NoSpace => "NO-SPACE",
        Error::Exists => "EXISTS",
        Error::Corrupt => "CORRUPT",
        Error::BufferTooSmall => "BUFFER",
        Error::BadContainer => "CONTAINER",
        Error::Compression => "COMPRESS",
        Error::BadName => "BAD-NAME",
    }
}

fn fault_name(fault: TransportFault) -> &'static str {
    match fault {
        TransportFault::None => "NONE",
        TransportFault::TxTimeout => "TX-TIMEOUT",
        TransportFault::RxTimeout => "RX-TIMEOUT",
        TransportFault::AckTimeout => "ACK-TIMEOUT",
        TransportFault::AckReleaseTimeout => "ACK-RELEASE",
    }
}

struct Text {
    bytes: [u8; 64],
    len: usize,
}

impl Text {
    const fn new() -> Self {
        Self {
            bytes: [0; 64],
            len: 0,
        }
    }

    fn clear(&mut self) {
        self.len = 0;
    }

    fn push(&mut self, text: &str) {
        for &byte in text.as_bytes() {
            if self.len < self.bytes.len() {
                self.bytes[self.len] = byte;
                self.len += 1;
            }
        }
    }

    fn dec(&mut self, value: u32) {
        let mut digits = [0u8; 10];
        let mut n = value;
        let mut len = 0;
        loop {
            digits[len] = b'0' + (n % 10) as u8;
            len += 1;
            n /= 10;
            if n == 0 {
                break;
            }
        }
        while len > 0 {
            len -= 1;
            self.push_byte(digits[len]);
        }
    }

    fn hex8(&mut self, value: u8) {
        self.push_byte(hex(value >> 4));
        self.push_byte(hex(value & 15));
    }

    fn hex32(&mut self, value: u32) {
        let mut shift = 28;
        loop {
            self.push_byte(hex(((value >> shift) & 15) as u8));
            if shift == 0 {
                break;
            }
            shift -= 4;
        }
    }

    fn push_byte(&mut self, byte: u8) {
        if self.len < self.bytes.len() {
            self.bytes[self.len] = byte;
            self.len += 1;
        }
    }

    fn as_str(&self) -> &str {
        // SAFETY: every append path emits ASCII.
        unsafe { core::str::from_utf8_unchecked(&self.bytes[..self.len]) }
    }
}

fn hex(value: u8) -> u8 {
    if value < 10 {
        b'0' + value
    } else {
        b'A' + value - 10
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! Recovery logic for the one malformed save created by the first hardware
//! diagnostic disc. This intentionally lives in the diagnostic, not `psx-mc`.

use psx_mc::{Block, Card, Error, Result, DATA_BLOCKS, FRAME_SIZE};

const E_STATE: usize = 0;
const E_SIZE: usize = 4;
const E_LINK: usize = 8;
const E_NAME: usize = 10;
const E_CHK: usize = 127;
const ST_FIRST: u8 = 0x51;
const ST_MIDDLE: u8 = 0x52;
const ST_LAST: u8 = 0x53;
const LINK_NONE: u16 = 0xffff;
const BLOCK_BYTES: u32 = 0x2000;

/// Return the correct allocated size only if the card has exactly one named
/// entry with `legacy_size`, every chain is structurally sound, and every
/// other entry already has a BIOS-compatible allocated size.
pub fn exact_legacy_size_target<B: Block>(
    card: &mut Card<B>,
    name: &str,
    legacy_size: u32,
) -> Result<Option<u32>> {
    let mut header = [0u8; FRAME_SIZE];
    card.device().read_frame(0, &mut header)?;
    if header[0] != b'M' || header[1] != b'C' {
        return Err(Error::NotFormatted);
    }
    if checksum(&header) != header[E_CHK] {
        return Err(Error::Corrupt);
    }

    let mut states = [0u8; DATA_BLOCKS];
    let mut links = [LINK_NONE; DATA_BLOCKS];
    let mut sizes = [0u32; DATA_BLOCKS];
    let mut named = [false; DATA_BLOCKS];
    let mut named_count = 0u8;
    for index in 0..DATA_BLOCKS {
        let entry = read_dir(card, index)?;
        if checksum(&entry) != entry[E_CHK] {
            return Err(Error::Corrupt);
        }
        let state = entry[E_STATE];
        if !is_free(state) && !matches!(state, ST_FIRST | ST_MIDDLE | ST_LAST) {
            return Err(Error::Corrupt);
        }
        states[index] = state;
        links[index] = u16::from_le_bytes([entry[E_LINK], entry[E_LINK + 1]]);
        sizes[index] = read_u32(&entry[E_SIZE..]);
        if state == ST_FIRST && entry_name_eq(&entry, name.as_bytes()) {
            named[index] = true;
            named_count = named_count.saturating_add(1);
        }
    }
    if named_count > 1 {
        return Ok(None);
    }

    let mut visited = 0u16;
    let mut target = None;
    for first in 0..DATA_BLOCKS {
        if states[first] != ST_FIRST {
            continue;
        }
        let mut current = first;
        let mut first_node = true;
        let mut chain_len = 0u32;
        loop {
            let bit = 1u16 << current;
            if visited & bit != 0 {
                return Err(Error::Corrupt);
            }
            visited |= bit;
            chain_len += 1;

            let state = states[current];
            if first_node {
                if state != ST_FIRST {
                    return Err(Error::Corrupt);
                }
                first_node = false;
            } else if !matches!(state, ST_MIDDLE | ST_LAST) {
                return Err(Error::Corrupt);
            }

            let link = links[current];
            if state == ST_LAST || (state == ST_FIRST && link == LINK_NONE) {
                if link != LINK_NONE {
                    return Err(Error::Corrupt);
                }
                break;
            }
            if link == LINK_NONE || link as usize >= DATA_BLOCKS {
                return Err(Error::Corrupt);
            }
            current = link as usize;
        }

        let expected = chain_len * BLOCK_BYTES;
        if named[first] {
            if sizes[first] != legacy_size || sizes[first] == expected {
                return Ok(None);
            }
            target = Some(expected);
        } else if sizes[first] != expected {
            return Err(Error::Corrupt);
        }
    }

    for index in 0..DATA_BLOCKS {
        if matches!(states[index], ST_MIDDLE | ST_LAST) && visited & (1u16 << index) == 0 {
            return Err(Error::Corrupt);
        }
    }
    Ok(target)
}

/// Repair the exact legacy entry by writing one directory frame, read it back,
/// and run the SDK's strict validator. The caller remains responsible for
/// authenticating the diagnostic payload before calling this function.
pub fn repair_exact_legacy_size<B: Block>(
    card: &mut Card<B>,
    name: &str,
    legacy_size: u32,
) -> Result<u32> {
    let expected = exact_legacy_size_target(card, name, legacy_size)?.ok_or(Error::Corrupt)?;
    let mut target = None;
    for index in 0..DATA_BLOCKS {
        let entry = read_dir(card, index)?;
        if entry[E_STATE] == ST_FIRST && entry_name_eq(&entry, name.as_bytes()) {
            if target.is_some() {
                return Err(Error::Corrupt);
            }
            target = Some((index, entry));
        }
    }
    let (index, mut entry) = target.ok_or(Error::NotFound)?;
    if checksum(&entry) != entry[E_CHK] || read_u32(&entry[E_SIZE..]) != legacy_size {
        return Err(Error::Corrupt);
    }

    entry[E_SIZE..E_SIZE + 4].copy_from_slice(&expected.to_le_bytes());
    entry[E_CHK] = checksum(&entry);
    card.device().write_frame(1 + index as u16, &entry)?;
    if read_dir(card, index)? != entry {
        return Err(Error::Corrupt);
    }
    card.validate_filesystem()?;
    Ok(expected)
}

fn read_dir<B: Block>(card: &mut Card<B>, index: usize) -> Result<[u8; FRAME_SIZE]> {
    let mut entry = [0u8; FRAME_SIZE];
    card.device().read_frame(1 + index as u16, &mut entry)?;
    Ok(entry)
}

fn checksum(frame: &[u8; FRAME_SIZE]) -> u8 {
    frame[..E_CHK].iter().fold(0u8, |sum, byte| sum ^ byte)
}

fn read_u32(bytes: &[u8]) -> u32 {
    u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]])
}

fn is_free(state: u8) -> bool {
    state & 0xf0 == 0xa0
}

fn entry_name_eq(entry: &[u8; FRAME_SIZE], name: &[u8]) -> bool {
    if name.len() > 20 || &entry[E_NAME..E_NAME + name.len()] != name {
        return false;
    }
    name.len() == 20 || entry[E_NAME + name.len()] == 0
}

#[cfg(test)]
mod tests {
    extern crate std;

    use super::{exact_legacy_size_target, repair_exact_legacy_size};
    use psx_mc::{Card, Entry, Error, RamCard, CARD_SIZE, DATA_BLOCKS, FRAME_SIZE, MAX_NAME_LEN};
    use std::vec::Vec;

    const TARGET: &str = "BESLES-00000PSXMC01";
    const BEFORE: &str = "BESLES-00000BEFORE1";
    const AFTER: &str = "BESLES-00000AFTER01";

    fn card_with_legacy_entry() -> Vec<u8> {
        let mut card = Card::new(RamCard::new());
        card.format().unwrap();
        card.write(BEFORE, "BEFORE", b"before").unwrap();
        card.write(TARGET, "PSOXIDE MC HARDWARE TEST", &[0x5a; 64])
            .unwrap();
        card.write(AFTER, "AFTER", b"after").unwrap();
        let mut image = card.into_inner().image().to_vec();
        set_directory_size(&mut image, 1, 0x50);
        image
    }

    #[test]
    fn changes_only_target_size_and_checksum_then_survives_cold_boot() {
        let image = card_with_legacy_entry();
        let before = image.clone();
        let mut card = Card::new(RamCard::from_image(&image).unwrap());
        assert_eq!(card.validate_filesystem(), Err(Error::Corrupt));
        assert_eq!(
            exact_legacy_size_target(&mut card, TARGET, 0x50),
            Ok(Some(0x2000))
        );
        assert_eq!(
            repair_exact_legacy_size(&mut card, TARGET, 0x50),
            Ok(0x2000)
        );

        let after = card.into_inner().image().to_vec();
        let base = (1 + 1) * FRAME_SIZE;
        let changed: Vec<_> = (0..CARD_SIZE)
            .filter(|&index| before[index] != after[index])
            .collect();
        assert_eq!(changed, [base + 4, base + 5, base + 127]);

        let mut cold_boot = Card::new(RamCard::from_image(&after).unwrap());
        cold_boot.validate_filesystem().unwrap();
        let mut entries = [blank_entry(); DATA_BLOCKS];
        assert_eq!(cold_boot.list(&mut entries).unwrap(), 3);
        assert_eq!(entries[0].name(), BEFORE);
        assert_eq!(entries[1].name(), TARGET);
        assert_eq!(entries[2].name(), AFTER);
    }

    #[test]
    fn refuses_wrong_size_name_or_unrelated_corruption() {
        let image = card_with_legacy_entry();
        let mut card = Card::new(RamCard::from_image(&image).unwrap());
        assert_eq!(exact_legacy_size_target(&mut card, TARGET, 0x60), Ok(None));
        assert_eq!(
            exact_legacy_size_target(&mut card, "BESLES-00000UNKNOWN", 0x50),
            Err(Error::Corrupt)
        );

        let mut image = image;
        set_directory_size(&mut image, 2, 0x60);
        let mut card = Card::new(RamCard::from_image(&image).unwrap());
        assert_eq!(
            exact_legacy_size_target(&mut card, TARGET, 0x50),
            Err(Error::Corrupt)
        );
        assert_eq!(
            repair_exact_legacy_size(&mut card, TARGET, 0x50),
            Err(Error::Corrupt)
        );
    }

    fn set_directory_size(image: &mut [u8], index: usize, size: u32) {
        let base = (1 + index) * FRAME_SIZE;
        image[base + 4..base + 8].copy_from_slice(&size.to_le_bytes());
        image[base + 127] = image[base..base + 127]
            .iter()
            .fold(0u8, |sum, byte| sum ^ byte);
    }

    const fn blank_entry() -> Entry {
        Entry {
            name: [0; MAX_NAME_LEN + 1],
            name_len: 0,
            blocks: 0,
        }
    }
}

//! `hello-memprobe` -- do `psx-rt`'s hand-scheduled `memcpy` / `memset` /
//! `memcmp` behave exactly like the C definitions on the target?
//!
//! Every size and alignment combination up to a few words past the block
//! loop, plus a few long copies, is run through the real symbols (sizes go
//! through `core::hint::black_box` so LLVM emits calls instead of inline
//! expansions) and checked bytewise against a reference loop, guard bytes
//! included. The verdict is printed on the TTY (`MEMPROBE PASS` /
//! `MEMPROBE FAIL <count>`) and drawn on screen.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::hint::black_box;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_rt::tty;
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

extern "C" {
    fn memcpy(dst: *mut u8, src: *const u8, n: usize) -> *mut u8;
    fn memset(dst: *mut u8, c: i32, n: usize) -> *mut u8;
    fn memcmp(a: *const u8, b: *const u8, n: usize) -> i32;
}

const BUF: usize = 1200;
const GUARD: u8 = 0xee;

static mut SRC: [u8; BUF] = [0; BUF];
static mut DST: [u8; BUF] = [0; BUF];
/// First failures as (kind, a, b, n, bad): kind 1 memcpy, 2 memset, 3 memcmp.
static mut LOG: [[u32; 5]; 16] = [[0; 5]; 16];
static mut LOGGED: usize = 0;

fn log_failure(kind: u32, a: usize, b: usize, n: usize, bad: u32) {
    unsafe {
        if LOGGED < 16 {
            LOG[LOGGED] = [kind, a as u32, b as u32, n as u32, bad];
            LOGGED += 1;
        }
    }
}

fn fill_pattern(buf: &mut [u8], seed: u8) {
    let mut v = seed;
    for b in buf.iter_mut() {
        *b = v;
        v = v.wrapping_mul(31).wrapping_add(7);
    }
}

/// One memcpy of `n` bytes from `src + so` to `dst + do_`; returns the count
/// of wrong bytes (copied region and one guard word on each side).
fn check_memcpy(so: usize, do_: usize, n: usize) -> u32 {
    let (src, dst) = unsafe {
        (
            &mut *core::ptr::addr_of_mut!(SRC),
            &mut *core::ptr::addr_of_mut!(DST),
        )
    };
    fill_pattern(src, (so + n) as u8);
    for b in dst.iter_mut() {
        *b = GUARD;
    }
    let ret = unsafe {
        memcpy(
            dst.as_mut_ptr().add(do_),
            src.as_ptr().add(so),
            black_box(n),
        )
    };
    let mut bad = 0u32;
    if ret != unsafe { dst.as_mut_ptr().add(do_) } {
        bad += 1;
    }
    for i in 0..n {
        if dst[do_ + i] != src[so + i] {
            bad += 1;
        }
    }
    for i in do_.saturating_sub(4)..do_ {
        if dst[i] != GUARD {
            bad += 1;
        }
    }
    for i in (do_ + n)..(do_ + n + 4).min(BUF) {
        if dst[i] != GUARD {
            bad += 1;
        }
    }
    bad
}

fn check_memset(do_: usize, n: usize, value: u8) -> u32 {
    let dst = unsafe { &mut *core::ptr::addr_of_mut!(DST) };
    for b in dst.iter_mut() {
        *b = GUARD;
    }
    // The high bits of `c` must be ignored, as in C.
    let c = (value as i32) | 0x1234_5600;
    let ret = unsafe { memset(dst.as_mut_ptr().add(do_), black_box(c), black_box(n)) };
    let mut bad = 0u32;
    if ret != unsafe { dst.as_mut_ptr().add(do_) } {
        bad += 1;
    }
    for i in 0..n {
        if dst[do_ + i] != value {
            bad += 1;
        }
    }
    for i in do_.saturating_sub(4)..do_ {
        if dst[i] != GUARD {
            bad += 1;
        }
    }
    for i in (do_ + n)..(do_ + n + 4).min(BUF) {
        if dst[i] != GUARD {
            bad += 1;
        }
    }
    bad
}

fn reference_memcmp(a: &[u8], b: &[u8]) -> i32 {
    for i in 0..a.len() {
        if a[i] != b[i] {
            return a[i] as i32 - b[i] as i32;
        }
    }
    0
}

/// Compare `n` bytes at offsets `ao`/`bo`; `differ_at` (if < n) flips one
/// byte of `b` so the sign and position handling is exercised.
fn check_memcmp(ao: usize, bo: usize, n: usize, differ_at: usize, up: bool) -> u32 {
    let (a, b) = unsafe {
        (
            &mut *core::ptr::addr_of_mut!(SRC),
            &mut *core::ptr::addr_of_mut!(DST),
        )
    };
    fill_pattern(a, (n + differ_at) as u8);
    b.copy_from_slice(a);
    // Shift b so the two views hold the same bytes at different alignments.
    for i in 0..n {
        b[bo + i] = a[ao + i];
    }
    if differ_at < n {
        b[bo + differ_at] = if up {
            a[ao + differ_at].wrapping_add(1)
        } else {
            a[ao + differ_at].wrapping_sub(1)
        };
        // Keep the reference honest when the wrap changed the sign.
    }
    let got = unsafe { memcmp(a.as_ptr().add(ao), b.as_ptr().add(bo), black_box(n)) };
    let want = reference_memcmp(&a[ao..ao + n], &b[bo..bo + n]);
    let same_sign = (got == 0 && want == 0) || (got < 0 && want < 0) || (got > 0 && want > 0);
    if same_sign {
        0
    } else {
        let bytes = ((a[ao] as usize) << 24)
            | ((b[bo] as usize) << 16)
            | ((a[ao + n - 1] as usize) << 8)
            | (b[bo + n - 1] as usize);
        log_failure(
            4,
            got as u32 as usize,
            want as u32 as usize,
            bytes,
            (differ_at as u32) << 1 | u32::from(up),
        );
        1
    }
}

fn run_all() -> (u32, u32) {
    let mut cases = 0u32;
    let mut failures = 0u32;
    let sizes: [usize; 22] = [
        0, 1, 2, 3, 4, 5, 7, 8, 12, 15, 16, 17, 20, 31, 32, 33, 47, 48, 63, 64, 100, 257,
    ];
    for &n in sizes.iter() {
        for so in 0..4 {
            for do_ in 0..4 {
                cases += 1;
                let bad = check_memcpy(so + 8, do_ + 8, n);
                if bad != 0 {
                    failures += 1;
                    log_failure(1, so + 8, do_ + 8, n, bad);
                }
            }
        }
        for do_ in 0..4 {
            for value in [0x5au8, 0x00] {
                cases += 1;
                let bad = check_memset(do_ + 8, n, value);
                if bad != 0 {
                    failures += 1;
                    log_failure(2, value as usize, do_ + 8, n, bad);
                }
            }
        }
        for ao in 0..4 {
            for bo in 0..4 {
                let positions = [n, 0, n / 2, n.saturating_sub(1), 4, 5, 9, 17];
                for &p in positions.iter() {
                    if p > n {
                        continue;
                    }
                    for up in [true, false] {
                        cases += 1;
                        let bad = check_memcmp(ao + 8, bo + 8, n, p, up);
                        if bad != 0 {
                            failures += 1;
                            log_failure(3, ao + 8, bo + 8, n, (p as u32) << 1 | u32::from(up));
                        }
                    }
                }
            }
        }
    }
    // Long copies past the block loop with every alignment pair.
    for &n in [1000usize, 1023, 1024, 1100].iter() {
        for so in 0..4 {
            for do_ in 0..4 {
                cases += 1;
                let bad = check_memcpy(so + 8, do_ + 8, n);
                if bad != 0 {
                    failures += 1;
                    log_failure(1, so + 8, do_ + 8, n, bad);
                }
            }
        }
        cases += 1;
        let bad = check_memset(9, n, 0xa5);
        if bad != 0 {
            failures += 1;
            log_failure(2, 0xa5, 9, n, bad);
        }
    }
    (cases, failures)
}

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);

    let (cases, failures) = run_all();
    if failures == 0 {
        tty::print("MEMPROBE PASS cases=");
        tty::print_hex_u32(cases);
        tty::println("");
    } else {
        tty::print("MEMPROBE FAIL ");
        tty::print_hex_u32(failures);
        tty::print(" of ");
        tty::print_hex_u32(cases);
        tty::println("");
        let logged = unsafe { LOGGED };
        for entry in unsafe { LOG[..logged].iter() } {
            tty::print("  kind/a/b/n/bad ");
            for value in entry.iter() {
                tty::print_hex_u32(*value);
                tty::print(" ");
            }
            tty::println("");
        }
    }

    loop {
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "MEM PROBE (memcpy/memset/memcmp)", (220, 220, 230));
        let (banner, tint) = if failures == 0 {
            ("ALL PASS", GREEN)
        } else {
            ("FAIL", RED)
        };
        font.draw_text(8, 30, banner, tint);
        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

//! `hello-ot` -- submit GPU primitives via an ordering table and
//! DMA channel 2 in linked-list mode, the same path a commercial
//! game uses.
//!
//! Draws three overlapping Gouraud triangles back-to-front; the
//! OT's depth sort determines the draw order. Running this
//! exercises the full commercial-game rendering pipe:
//!
//! 1. Start a frame: clear the OT (sets up the inter-slot chain).
//! 2. Write the primitive packets into storage the frame borrows.
//! 3. Prepend each into the OT at its Z slot.
//! 4. Fill a background rect.
//! 5. Submit the OT to GP0 via DMA linked-list and wait for the walk.
//! 6. VSync.
//!
//! The frame borrows the table and every packet until the walk is over,
//! so the borrow checker, not an `unsafe` block, proves the DMA never
//! reads a packet that is gone or changing.
//!
//! Each triangle drifts on a sine wave -- smooth back-and-forth,
//! no modulo snap-back. `psx-math::sincos` supplies the Q1.12
//! trig table (one LUT lookup per frame per triangle).

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::ot::OrderingTable;
use psx_gpu::prim::TriGouraud;
use psx_gpu::Gpu;
use psx_math::sincos;
use psx_rt::Peripherals;

/// Pixel displacement for a sine-driven drift. `phase_q12` is a
/// Q0.12 angle (one full revolution = 4096); amplitude is the
/// peak pixel displacement on either side of the centre.
#[inline]
fn drift(phase_q12: u16, amplitude_px: i16) -> i16 {
    // `sin_q12` returns Q1.12 in [-4096, 4096]. Multiply by amp
    // and shift 12 to scale back into pixels.
    ((sincos::sin_q12(phase_q12) * amplitude_px as i32) >> 12) as i16
}

#[no_mangle]
fn main() {
    let Some(peripherals) = Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));

    // The table and the packets live on `main`'s stack, which outlives
    // every frame; each frame borrows them until its walk is done.
    let mut ot = OrderingTable::<16>::new();
    let mut tris: [TriGouraud; 3] =
        core::array::from_fn(|_| TriGouraud::new([(0, 0); 3], [(0, 0, 0); 3]));

    let mut frame: u32 = 0;
    loop {
        // Each triangle gets a sine-driven offset at a different
        // frequency + phase. Angle steps are Q0.12 per frame --
        // 32/frame = ~4.2 s per rev; 48/frame = ~2.8 s. The full
        // cycle runs forever with no modulo-snap jumps.
        let phase_red = (frame.wrapping_mul(32) & 0xfff) as u16;
        let phase_green = (frame.wrapping_mul(48).wrapping_add(1365) & 0xfff) as u16; // +120°
        let phase_blue = (frame.wrapping_mul(40).wrapping_add(2731) & 0xfff) as u16; // +240°

        let red_dx = drift(phase_red, 30);
        // Green moves vertically so the three axes differ.
        let green_dy = drift(phase_green, 22);
        let blue_dx = drift(phase_blue, 34);

        // Three overlapping triangles at different depth slots.
        // Slot 0 = front, slot 15 = back (ordering-table walker
        // visits slot N-1 first, slot 0 last → later = on top).
        // Vertex coordinates are in draw-offset-relative space,
        // which `DoubleBuffer::swap` keeps pointing at the current
        // back buffer for us.
        let red = TriGouraud::new(
            [(120 + red_dx, 60), (40 + red_dx, 160), (200 + red_dx, 160)],
            [(220, 80, 80), (80, 220, 80), (80, 80, 220)],
        );
        let green = TriGouraud::new(
            [
                (160, 40 + green_dy),
                (80, 180 + green_dy),
                (240, 160 + green_dy),
            ],
            [(80, 200, 120), (200, 80, 120), (120, 80, 200)],
        );
        let blue = TriGouraud::new(
            [
                (180 + blue_dx, 80),
                (120 + blue_dx, 200),
                (260 + blue_dx, 170),
            ],
            [(80, 160, 220), (220, 120, 80), (160, 220, 80)],
        );

        let mut ot_frame = ot.frame();
        let [back, middle, front] = &mut tris;
        *back = red;
        *middle = green;
        *front = blue;
        ot_frame.add(10, back);
        ot_frame.add(8, middle);
        ot_frame.add(6, front);

        fb.clear(&mut gpu, (0, 0, 48));
        ot_frame.submit(gpu.dma_mut());

        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
        frame = frame.wrapping_add(1);
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! Same-compilation Rust entry/import, borrowed arena and unload/re-admit probe.
#![no_std]
#![no_main]
extern crate psx_rt;

use psx_residency::arena::{checksum, CallerArena, Descriptor, Registry, StaticImport};
use psx_rt::tty;

// The packer writes this fixed-capacity transport fixture after linking. The
// production boundary accepts the identical completed words from caller CD I/O.
#[used]
#[no_mangle]
#[link_section = ".data.overlay_payload"]
static mut OVERLAY_PAYLOAD: [u32; 1024] = [0; 1024];
#[used]
#[no_mangle]
#[link_section = ".data.overlay_descriptor"]
static mut OVERLAY_DESCRIPTOR: [u32; 4] = [0; 4]; // words, checksum, callsite, entry

// This models a game's existing scene/title workspace, rather than reserving
// an arena inside the SDK. Gameplay overwrites it between title admissions.
#[repr(C, align(16))]
struct Workspace([u32; 1024]);
static mut WORKSPACE: Workspace = Workspace([0; 1024]);

struct State {
    count: u32,
    value: f32,
}

#[inline(never)]
#[no_mangle]
fn overlay_resident_service(value: f32) -> f32 {
    value * 1.5 + 0.25
}

// The function uses the exact private Rust type shared with its resident
// caller. No separate ABI declarations or serialized game-state struct exist.
#[inline(never)]
#[link_section = ".overlay.text"]
#[no_mangle]
unsafe fn overlay_cold_update(state: &mut State, frames: u32) -> u32 {
    state.count = state.count.wrapping_add(frames);
    state.value = overlay_resident_service(state.value);
    state.count
}

#[inline(never)]
#[no_mangle]
unsafe fn overlay_typed_call(state: &mut State, frames: u32) -> u32 {
    // Keep work after the call so this is a direct JAL, not a tail jump.
    let result = overlay_cold_update(state, frames);
    core::hint::black_box(result)
}

#[inline(never)]
#[no_mangle]
fn overlay_unloaded_trap() -> ! {
    tty::println("OVERLAY UNLOADED CALL FAIL");
    loop {
        core::hint::spin_loop();
    }
}

#[no_mangle]
fn main() {
    // SAFETY: single-threaded probe; no DMA, interrupts or asynchronous users
    // touch workspace, payload or the typed callsite during these scopes.
    let passed = unsafe { probe() };
    tty::println(if passed {
        "CALLER ARENA OVERLAY PASS"
    } else {
        "CALLER ARENA OVERLAY FAIL"
    });
    loop {
        core::hint::spin_loop();
    }
}

unsafe fn probe() -> bool {
    let descriptor = (&raw const OVERLAY_DESCRIPTOR).read();
    if descriptor[0] == 0 || descriptor[0] > 1024 {
        return false;
    }
    let payload = core::slice::from_raw_parts(
        (&raw const OVERLAY_PAYLOAD).cast::<u32>(),
        descriptor[0] as usize,
    );
    if checksum(payload) != descriptor[1] {
        return false;
    }
    let info = Descriptor {
        id: 1,
        linked: 0x80408000,
        checksum: descriptor[1],
    };
    let backing = &mut *(&raw mut WORKSPACE);
    let address = backing.0.as_mut_ptr() as usize as u32;
    let mut registry = Registry::<1>::new(1, 4096);
    let mut state = State {
        count: 0,
        value: 2.0,
    };
    let first;
    {
        let mut arena = match CallerArena::new(&mut backing.0, address) {
            Ok(v) => v,
            Err(_) => return false,
        };
        first = match registry.install(&mut arena, payload, info) {
            Ok(v) => v,
            Err(_) => return false,
        };
        let dependencies = [first];
        let admission = match registry.admit(&mut arena, &dependencies) {
            Ok(v) => v,
            Err(_) => return false,
        };
        let site = descriptor[2];
        let mut imports = [StaticImport::new(
            &mut *(site as *mut u32),
            site,
            first,
            descriptor[3],
        )];
        if admission.invoke(
            &mut imports,
            overlay_unloaded_trap as *const () as usize as u32,
            || overlay_typed_call(&mut state, 7),
        ) != Ok(7)
        {
            return false;
        }
    }
    tty::print("overlay first count=");
    tty::print_hex_u32(state.count);
    tty::print(" float=");
    tty::print_hex_u32(state.value.to_bits());
    tty::println("");
    let trap_target = overlay_unloaded_trap as *const () as usize as u32;
    let trapped_target = || {
        let instruction = (descriptor[2] as *const u32).read_volatile();
        ((descriptor[2] + 4) & 0xf0000000) | ((instruction & 0x03ffffff) << 2)
    };
    if trapped_target() != trap_target {
        return false;
    }
    registry.invalidate_all();
    // No live admission or module view exists while gameplay reuses storage.
    backing.0.fill(0xdeadbeef);
    {
        let mut arena = match CallerArena::new(&mut backing.0, address) {
            Ok(v) => v,
            Err(_) => return false,
        };
        let second = match registry.install(&mut arena, payload, info) {
            Ok(v) => v,
            Err(_) => return false,
        };
        if registry.admit(&mut arena, &[first]).is_ok() {
            return false;
        }
        let dependencies = [second];
        let admission = match registry.admit(&mut arena, &dependencies) {
            Ok(v) => v,
            Err(_) => return false,
        };
        let site = descriptor[2];
        let mut imports = [StaticImport::new(
            &mut *(site as *mut u32),
            site,
            second,
            descriptor[3],
        )];
        if admission.invoke(
            &mut imports,
            overlay_unloaded_trap as *const () as usize as u32,
            || overlay_typed_call(&mut state, 5),
        ) != Ok(12)
        {
            return false;
        }
    }
    tty::print("overlay reloaded count=");
    tty::print_hex_u32(state.count);
    tty::print(" float=");
    tty::print_hex_u32(state.value.to_bits());
    tty::println("");
    state.count == 12 && state.value == 5.125 && trapped_target() == trap_target
}

//! `hello-pack` -- a `psx_pack::cd` smoke test that streams WORLD.PAK chunks
//! off the disc on boot and paints the result, so it can be verified
//! headlessly (dump the frame and read the PASS/FAIL banner, or grep the TTY
//! for `hello-pack: ALL PASS`).
//!
//! The disc is built by `make hello-pack-disc`: an 86-chunk fixture pack
//! (ids 0..=85) whose chunk table spans two sectors, so entry 84 straddles
//! the sector boundary and the reader's stitched entry parse runs against
//! real CD reads. Chunk 84 is an incompressible pattern (stored raw even
//! under `--world-pack-compress-rooms`); chunk 85 is a run pattern the
//! packer LZ4/HLZC-frames. Both patterns are recomputed here and must match
//! `tools/hello_pack_fixture.py` byte for byte.
//!
//! Steps, each shown as a line: prepare the reader, locate + load + FNV-check
//! + content-check the raw chunk, the same for the compressed chunk through
//! `load_chunk_decompressed`, and a lookup of an absent id. A green screen
//! with `ALL PASS` means table scan (straddle included), payload streaming,
//! checksums, and in-place decompression all work end-to-end off the disc.
//! A last line checks the reader put the interrupt mask back after its loads.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::ptr::addr_of_mut;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_pack::cd::{
    find_entry, load_chunk, load_chunk_decompressed, SectorReader, SECTOR_WORDS,
    WORLD_PACK_DEFAULT_LBA,
};
use psx_pack::fnv1a32;
use psx_rt::tty;
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);

const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

// Fixture layout, in lockstep with tools/hello_pack_fixture.py.
const RAW_ID: u32 = 84; // its table entry straddles header sectors 0/1
const RAW_LEN: usize = 3000; // 2 sectors, partial tail
const COMP_ID: u32 = 85;
const COMP_LEN: usize = 5000; // raw length; stored HLZC-compressed

/// Incompressible pattern for chunk 84: murmur3-finalizer avalanche of the
/// index. (A plain multiplicative hash is not enough; its high bits form a
/// near-arithmetic sequence and LZ4 shrinks it, turning the chunk HLZC.)
fn raw_byte(k: usize) -> u8 {
    let mut h = (k as u32).wrapping_add(RAW_ID.wrapping_mul(2_654_435_761));
    h ^= h >> 16;
    h = h.wrapping_mul(0x85eb_ca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2_ae35);
    h ^= h >> 16;
    h as u8
}

/// Compressible pattern for chunk 85 (64-byte runs).
fn comp_byte(k: usize) -> u8 {
    (((k >> 6) as u32 + COMP_ID) & 0xff) as u8
}

// The reader owns a one-sector bounce buffer and dst must hold the biggest
// raw chunk plus the in-place LZ4 margin, so keep them off the 32 KiB stack.
static mut READER: Option<SectorReader> = None;
static mut SCRATCH: [u32; SECTOR_WORDS] = [0; SECTOR_WORDS];
const DST_WORDS: usize = 3072; // 12 KiB
static mut DST: [u32; DST_WORDS] = [0; DST_WORDS];

/// Up to this many result lines are recorded, then rendered every frame.
struct Report {
    lines: [Line; 12],
    len: usize,
    all_ok: bool,
    failed: &'static str,
}

#[derive(Copy, Clone)]
struct Line {
    text: &'static str,
    ok: bool,
}

impl Report {
    fn new() -> Self {
        Report {
            lines: [Line { text: "", ok: true }; 12],
            len: 0,
            all_ok: true,
            failed: "",
        }
    }

    /// Record one stage; echo it to TTY; `false` means stop the run.
    fn check(&mut self, label: &'static str, ok: bool) -> bool {
        if self.len < self.lines.len() {
            self.lines[self.len] = Line { text: label, ok };
            self.len += 1;
        }
        tty::print("hello-pack: ");
        tty::print(label);
        tty::println(if ok { " ok" } else { " FAIL" });
        if !ok {
            self.all_ok = false;
            if self.failed.is_empty() {
                self.failed = label;
            }
        }
        ok
    }
}

fn dst_bytes(dst: &[u32]) -> &[u8] {
    // SAFETY: [u32] viewed as its own bytes (little-endian target).
    unsafe { core::slice::from_raw_parts(dst.as_ptr() as *const u8, dst.len() * 4) }
}

fn bytes_match(bytes: &[u8], expect: fn(usize) -> u8) -> bool {
    let mut k = 0;
    while k < bytes.len() {
        if bytes[k] != expect(k) {
            return false;
        }
        k += 1;
    }
    true
}

/// Run the whole test and return the filled report.
fn run(rd: &mut SectorReader) -> Report {
    let mut rep = Report::new();
    // Set a mask bit no source raises here (SIO1), so the check at the end can
    // tell a restored mask from the VBlank-only one the reader runs under.
    psx_io::irq::set_mask(psx_io::irq::mask() | (1 << 8));
    let mask_before = psx_io::irq::mask();
    // SAFETY: main runs once; these statics are only touched here.
    let scratch = unsafe { &mut *addr_of_mut!(SCRATCH) };
    let dst = unsafe { &mut *addr_of_mut!(DST) };

    // The reader holds VBlank-only I_MASK from here to its last stop(), which
    // matches what psx_rt::interrupts installs for wait_vblank anyway.
    if !rep.check("PREPARE", rd.prepare()) {
        return rep;
    }

    // Raw chunk: its entry is the one that straddles header sectors 0/1.
    let Some(e84) = find_entry(rd, WORLD_PACK_DEFAULT_LBA, RAW_ID, scratch) else {
        rep.check("ENTRY 84", false);
        return rep;
    };
    if !rep.check(
        "ENTRY 84",
        e84.byte_size as usize == RAW_LEN && e84.sector_count == 2,
    ) {
        return rep;
    }
    let loaded = load_chunk(rd, WORLD_PACK_DEFAULT_LBA, RAW_ID, scratch, dst);
    if !rep.check("LOAD 84", loaded == Some(RAW_LEN)) {
        return rep;
    }
    if !rep.check(
        "FNV 84",
        fnv1a32(&dst_bytes(dst)[..RAW_LEN]) == e84.checksum,
    ) {
        return rep;
    }
    if !rep.check("DATA 84", bytes_match(&dst_bytes(dst)[..RAW_LEN], raw_byte)) {
        return rep;
    }

    // Compressed chunk: stored HLZC-framed, so the table byte_size must be
    // smaller than the raw length, and the stored bytes carry the checksum.
    let Some(e85) = find_entry(rd, WORLD_PACK_DEFAULT_LBA, COMP_ID, scratch) else {
        rep.check("ENTRY 85", false);
        return rep;
    };
    if !rep.check("ENTRY 85 HLZC", (e85.byte_size as usize) < COMP_LEN) {
        return rep;
    }
    let stored = load_chunk(rd, WORLD_PACK_DEFAULT_LBA, COMP_ID, scratch, dst);
    if !rep.check("LOAD 85", stored == Some(e85.byte_size as usize)) {
        return rep;
    }
    if !rep.check(
        "FNV 85",
        fnv1a32(&dst_bytes(dst)[..e85.byte_size as usize]) == e85.checksum,
    ) {
        return rep;
    }
    let raw = load_chunk_decompressed(rd, WORLD_PACK_DEFAULT_LBA, COMP_ID, scratch, dst);
    if !rep.check("LOAD-C 85", raw == Some(COMP_LEN)) {
        return rep;
    }
    if !rep.check(
        "DATA 85",
        bytes_match(&dst_bytes(dst)[..COMP_LEN], comp_byte),
    ) {
        return rep;
    }

    // A chunk id the pack does not contain must miss cleanly.
    let absent = find_entry(rd, WORLD_PACK_DEFAULT_LBA, 0xdead_beef, scratch).is_none();
    // Every load above ran under the reader's VBlank-only mask; stop() put the
    // one we set back. Read it before anything else runs: TTY output goes
    // through the BIOS, which the emulator's HLE leaves with I_MASK rewritten.
    let mask_after = psx_io::irq::mask();
    if !rep.check("ABSENT ID", absent) {
        return rep;
    }
    rep.check("IRQ MASK RESTORED", mask_after == mask_before);
    rep
}

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);

    // Run once at boot; hold the result on screen.
    // SAFETY: main runs once; the static is only touched here.
    let rd = unsafe { (*addr_of_mut!(READER)).insert(SectorReader::with_cd(peripherals.cd)) };
    let rep = run(rd);
    if rep.all_ok {
        tty::println("hello-pack: ALL PASS");
    } else {
        tty::print("hello-pack: FAIL ");
        tty::println(rep.failed);
    }

    loop {
        // Whole-screen verdict color so a headless --dump-hw is unambiguous.
        if rep.all_ok {
            fb.clear(&mut gpu, (16, 96, 32));
        } else {
            fb.clear(&mut gpu, (110, 20, 20));
        }
        font.draw_text(8, 6, "PSX-PACK CD STREAM TEST", (230, 230, 240));
        let mut y: i16 = 26;
        for i in 0..rep.len {
            let l = rep.lines[i];
            let tint = if l.ok { GREEN } else { RED };
            font.draw_text(8, y, if l.ok { "OK" } else { "XX" }, tint);
            font.draw_text(32, y, l.text, tint);
            y += 12;
        }
        if rep.all_ok {
            font.draw_text(8, 210, "ALL PASS", (235, 255, 235));
        } else {
            font.draw_text(8, 210, "FAIL", (255, 235, 235));
            font.draw_text(72, 210, rep.failed, (255, 235, 235));
        }

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

//! `hello-present` -- psx-rt's queued display flip waits for the frame's
//! closing GP0(1Fh), not for GPUSTAT bit 28.
//!
//! On silicon bit 28 rises when the DMA has pushed a list's last packet,
//! about one large primitive before the drawing ends (hardware-tests v1.24
//! cases 219-226), so a flip gated on it can show a frame one primitive
//! short. psx-rt's VBlank handler now applies a queued display start only
//! once GPUSTAT bit 24 is set, which GP0(1Fh) raises when the GPU reaches
//! it. This example checks that contract end to end:
//!
//! 1. Held: a frame kicked without GP0(1Fh) keeps its flip queued, even
//!    after `wait_idle` has seen the GPU idle (the old bit-28 test would
//!    have flipped at the next edge).
//! 2. Released: `signal_draw_done` then lets the flip land within a few
//!    VBlanks.
//! 3. Pipelined: `FRAMES` frames of varying cost, each an ordering table
//!    closed with `end_with_draw_done`, armed with `arm_draw_done` and
//!    kicked asynchronously, flip through the queue with no timeout, and
//!    every flip is seen with its frame's GP0(1Fh) executed.
//!
//! The asynchronous kicks go through `FrameStorage::draw_async`: the table
//! and packets are `'static` and owned by the returned `InFlight` until
//! its `wait`, so no frame is rebuilt under a walk.
//!
//! The verdict goes to the TTY (`PRESENT PASS ...` or `PRESENT FAIL ...`)
//! and on screen.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::ptr::addr_of_mut;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::frame::{FrameStorage, OtFrame};
use psx_gpu::prim::TriGouraud;
use psx_gpu::{is_draw_done, Gpu};
use psx_rt::{interrupts, tty, Peripherals};
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const WHITE: (u8, u8, u8) = (220, 220, 230);
const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

/// Pipelined frames to present.
const FRAMES: u32 = 120;
/// VBlanks a queued flip is given before it counts as a timeout.
const WAIT_LIMIT: u32 = 8;
/// Most triangles in one frame; frame `f` draws `f % (TRIS + 1)`.
const TRIS: usize = 12;

const EMPTY: TriGouraud = TriGouraud::new([(0, 0); 3], [(0, 0, 0); 3]);
static mut FRAME: FrameStorage<8, [TriGouraud; TRIS]> = FrameStorage::new([EMPTY; TRIS]);

/// Wait until the queued flip is applied or `limit` VBlanks pass.
/// Returns whether it was applied.
fn wait_flip(limit: u32) -> bool {
    let start = interrupts::vblank_count();
    while interrupts::is_display_control_queued() {
        if interrupts::vblank_count().wrapping_sub(start) > limit {
            return false;
        }
    }
    true
}

/// Wait `n` VBlanks.
fn wait_vblanks(n: u32) {
    for _ in 0..n {
        interrupts::wait_vblank();
    }
}

/// Build frame `f`: `f % (TRIS + 1)` half-screen Gouraud triangles,
/// closed with GP0(1Fh) when `close` is set.
fn build_frame<'f>(
    frame: &mut OtFrame<'f, 8>,
    packets: &'f mut [TriGouraud; TRIS],
    f: u32,
    close: bool,
) {
    if close {
        frame.end_with_draw_done();
    }
    let count = (f as usize) % (TRIS + 1);
    for (t, packet) in packets.iter_mut().take(count).enumerate() {
        let shade = ((t as u32 * 20 + f * 3) & 0x7f) as u8 + 0x20;
        let verts = if t & 1 == 0 {
            [(0, 0), (319, 0), (0, 239)]
        } else {
            [(319, 239), (0, 239), (319, 0)]
        };
        *packet = TriGouraud::new(verts, [(shade, 0, 40), (0, shade, 40), (40, 0, shade)]);
        frame.add(1 + t % 6, packet);
    }
}

/// `label=XXXXXXXX` for the TTY and the screen.
fn line(label: &str, value: u32) -> ([u8; 32], usize) {
    const DIGITS: &[u8; 16] = b"0123456789ABCDEF";
    let mut text = [b' '; 32];
    let label = &label.as_bytes()[..label.len().min(22)];
    text[..label.len()].copy_from_slice(label);
    text[label.len()] = b'=';
    for i in 0..8 {
        text[label.len() + 1 + i] = DIGITS[(value >> (28 - 4 * i) & 0xf) as usize];
    }
    (text, label.len() + 9)
}

fn as_str(text: &[u8]) -> &str {
    core::str::from_utf8(text).unwrap_or("?")
}

#[no_mangle]
fn main() {
    interrupts::install_vblank_counter();
    let Some(peripherals) = Peripherals::take() else {
        return;
    };
    // The token moves into each in-flight frame and comes back from its
    // wait; between frames `Gpu::from_dma_mut` lends the driver.
    let display = DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240);
    let mut dma = Gpu::new(peripherals.gpu_dma, display).release();
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    fb.apply_draw_target(Gpu::from_dma_mut(&mut dma));
    // SAFETY: the only reference ever made to FRAME.
    let mut storage = unsafe { &mut *addr_of_mut!(FRAME) };

    // 1. Held: no GP0(1Fh), so the flip must stay queued even once the GPU
    // is idle.
    let gpu = Gpu::from_dma_mut(&mut dma);
    fb.clear(gpu, (8, 8, 24));
    gpu.arm_draw_done();
    let (in_flight, ()) = storage.draw_async(dma, |frame, packets| {
        build_frame(frame, packets, TRIS as u32, false)
    });
    interrupts::queue_display_control_at_vblank(fb.begin_deferred_swap());
    (storage, dma) = in_flight.wait();
    Gpu::from_dma_mut(&mut dma).wait_idle();
    wait_vblanks(4);
    let held = interrupts::is_display_control_queued() && !is_draw_done();

    // 2. Released: GP0(1Fh) through the port lets it land.
    Gpu::from_dma_mut(&mut dma).signal_draw_done();
    let released = wait_flip(4);
    if !released {
        let word = interrupts::take_queued_display_control();
        if word != 0 {
            psx_io::gpu::write_display_control(word);
        }
    }

    // 3. Pipelined frames through the queue.
    let mut timeouts = 0u32;
    let mut early = 0u32;
    let start = interrupts::vblank_count();
    for f in 0..FRAMES {
        let gpu = Gpu::from_dma_mut(&mut dma);
        fb.apply_draw_target(gpu);
        fb.clear(gpu, (8, 8, 24));
        gpu.arm_draw_done();
        let (in_flight, ()) =
            storage.draw_async(dma, |frame, packets| build_frame(frame, packets, f, true));
        interrupts::queue_display_control_at_vblank(fb.begin_deferred_swap());
        let flipped = wait_flip(WAIT_LIMIT);
        // A flip needs the frame drawn, so its walk is over and this wait
        // returns at once; after a timeout it ends the walk first.
        (storage, dma) = in_flight.wait();
        if !flipped {
            timeouts += 1;
            Gpu::from_dma_mut(&mut dma).wait_idle();
            let word = interrupts::take_queued_display_control();
            if word != 0 {
                psx_io::gpu::write_display_control(word);
            }
        } else if !is_draw_done() {
            // The flag cannot clear before the next arm, so a flip seen
            // without it happened before the frame's GP0(1Fh) ran.
            early += 1;
        }
    }
    let vblanks = interrupts::vblank_count().wrapping_sub(start);
    let gpu = Gpu::from_dma_mut(&mut dma);
    gpu.wait_idle();

    let checks = [
        (held, "flip without GP0(1Fh) was applied"),
        (released, "GP0(1Fh) did not release the flip"),
        (timeouts == 0, "queued flips timed out"),
        (early == 0, "flip before the frame's GP0(1Fh)"),
        (vblanks >= FRAMES, "fewer VBlanks than frames"),
        (interrupts::fault_count() == 0, "exceptions other than IRQs"),
    ];
    let failures = checks.iter().filter(|check| !check.0).count() as u32;
    for (_, what) in checks.iter().filter(|check| !check.0) {
        tty::print("PRESENT check failed: ");
        tty::println(what);
    }
    let lines = [
        line("failures", failures),
        line("frames", FRAMES),
        line("vblanks", vblanks),
        line("timeouts", timeouts),
        line("early", early),
    ];
    let (banner, tint) = if failures == 0 {
        ("PRESENT PASS", GREEN)
    } else {
        ("PRESENT FAIL", RED)
    };
    tty::print(banner);
    for (text, len) in &lines {
        tty::print(" ");
        tty::print(as_str(&text[..*len]));
    }
    tty::println("");

    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);
    loop {
        fb.apply_draw_target(gpu);
        fb.clear(gpu, (10, 12, 20));
        font.draw_text(8, 6, "QUEUED FLIP WAITS FOR GP0(1FH)", WHITE);
        font.draw_text(8, 30, banner, tint);
        for (row, (text, len)) in lines.iter().enumerate() {
            font.draw_text(8, 54 + 12 * row as i16, as_str(&text[..*len]), WHITE);
        }
        let mut y = 126;
        for (_, what) in checks.iter().filter(|check| !check.0) {
            font.draw_text(8, y, what, RED);
            y += 12;
        }
        gpu.arm_draw_done();
        gpu.signal_draw_done();
        interrupts::queue_display_control_at_vblank(fb.begin_deferred_swap());
        wait_flip(WAIT_LIMIT);
    }
}

//! `hello-present-queue` -- whole frames through psx-rt's VBlank-kicked
//! present queue (`psx_rt::present`, the `present-queue` feature).
//!
//! `FRAMES` frames of varying cost are each published as one chain: a
//! recorded preamble (draw target and clear), the ordering table, a recorded
//! HUD band, then GP0(1Fh). The CPU never kicks or flips: the VBlank handler
//! shows the previous frame and kicks the next chain on the first edge that
//! finds the one before it drawn. Everything a chain links is double
//! buffered, and `wait_arena_free` keeps the CPU off the side a walk may
//! still read.
//!
//! Every frame must be kicked exactly once, with no stall recovery and no
//! recording overflow. The verdict goes to the TTY
//! (`PRESENT-QUEUE PASS ...` or `PRESENT-QUEUE FAIL ...`) and on screen.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::ptr::addr_of_mut;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::chain::DRAW_DONE_NODE;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::ot::OrderingTable;
use psx_gpu::prim::{FillRect, TriGouraud};
use psx_gpu::Gpu;
use psx_io::gpu::start_recording_raw;
use psx_rt::{interrupts, present, tty};
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const WHITE: (u8, u8, u8) = (220, 220, 230);
const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

/// Frames to publish.
const FRAMES: u32 = 120;
/// VBlanks the final screen's flip is given.
const WAIT_LIMIT: u32 = 8;
/// Most triangles in one frame; frame `f` draws `f % (TRIS + 1)`.
const TRIS: usize = 12;

const EMPTY: TriGouraud = TriGouraud::new([(0, 0); 3], [(0, 0, 0); 3]);
// Frame N is built while N-1 may still walk, so every buffer a chain links
// comes in two.
static mut TABLES: [OrderingTable<8>; 2] = [OrderingTable::new(), OrderingTable::new()];
static mut PACKETS: [[TriGouraud; TRIS]; 2] = [[EMPTY; TRIS], [EMPTY; TRIS]];
static mut PREAMBLES: [[u32; 64]; 2] = [[0; 64]; 2];
static mut HUDS: [[u32; 1024]; 2] = [[0; 1024]; 2];

/// Wait until the queued flip is applied or `limit` VBlanks pass.
fn wait_flip(limit: u32) -> bool {
    let start = interrupts::vblank_count();
    while interrupts::is_display_control_queued() {
        if interrupts::vblank_count().wrapping_sub(start) > limit {
            return false;
        }
    }
    true
}

/// Build frame `f`'s triangles: `f % (TRIS + 1)` half-screen Gouraud
/// triangles in slots 1..=6, leaving slot 0 for the HUD link.
fn build_frame(table: &mut OrderingTable<8>, packets: &mut [TriGouraud; TRIS], f: u32) {
    let mut frame = table.frame();
    let count = (f as usize) % (TRIS + 1);
    for (t, packet) in packets.iter_mut().take(count).enumerate() {
        let shade = ((t as u32 * 20 + f * 3) & 0x7f) as u8 + 0x20;
        let verts = if t & 1 == 0 {
            [(0, 0), (319, 0), (0, 239)]
        } else {
            [(319, 239), (0, 239), (319, 0)]
        };
        *packet = TriGouraud::new(verts, [(shade, 0, 40), (0, shade, 40), (40, 0, shade)]);
        frame.add(1 + t % 6, packet);
    }
}

/// `label=XXXXXXXX` for the TTY and the screen.
fn line(label: &str, value: u32) -> ([u8; 32], usize) {
    const DIGITS: &[u8; 16] = b"0123456789ABCDEF";
    let mut text = [b' '; 32];
    let label = &label.as_bytes()[..label.len().min(22)];
    text[..label.len()].copy_from_slice(label);
    text[label.len()] = b'=';
    for i in 0..8 {
        text[label.len() + 1 + i] = DIGITS[(value >> (28 - 4 * i) & 0xf) as usize];
    }
    (text, label.len() + 9)
}

fn as_str(text: &[u8]) -> &str {
    core::str::from_utf8(text).unwrap_or("?")
}

#[no_mangle]
fn main() {
    interrupts::install_vblank_counter();
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    fb.apply_draw_target(&mut gpu);
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);
    gpu.wait_idle();

    interrupts::reset_flip_histogram();
    let before = present::stats();
    present::start();
    let mut overflows = 0u32;
    // GP1(05h) word of the last published frame; 0 before the first.
    let mut shown = 0u32;
    let start = interrupts::vblank_count();
    for f in 0..FRAMES {
        let side = (f & 1) as usize;
        // The chain two frames back linked this side's buffers.
        present::wait_arena_free();
        // SAFETY: `wait_arena_free` guarantees no walk reads this side, and
        // these are the only references made to it this frame.
        let (table, packets, preamble, hud) = unsafe {
            (
                &mut (*addr_of_mut!(TABLES))[side],
                &mut (*addr_of_mut!(PACKETS))[side],
                &mut (*addr_of_mut!(PREAMBLES))[side],
                &mut (*addr_of_mut!(HUDS))[side],
            )
        };
        build_frame(table, packets, f);

        // SAFETY: `hud` is static, and is not written again until
        // `wait_arena_free` says its walk has ended.
        let recording = unsafe { start_recording_raw(hud.as_mut_ptr(), hud.len()) };
        gpu.draw(&FillRect::new(
            (0, fb.draw_origin().1 + 200),
            (320, 40),
            (20, 24, 60),
        ));
        font.draw_text(8, 212, "QUEUED HUD", WHITE);
        match recording.end() {
            // SAFETY: the recording and the static GP0(1Fh) node live as long
            // as `hud`; the table's slot 0 is still empty.
            Ok(Some(recording)) => unsafe {
                recording.link_to(DRAW_DONE_NODE.as_ptr());
                table.end_with_chain(recording.head());
            },
            _ => {
                overflows += 1;
                table.end_with_draw_done();
            }
        }

        // SAFETY: as for `hud`.
        let recording = unsafe { start_recording_raw(preamble.as_mut_ptr(), preamble.len()) };
        fb.apply_draw_target(&mut gpu);
        fb.clear(&mut gpu, (8, 24, 8));
        let Ok(Some(preamble)) = recording.end() else {
            overflows += 1;
            continue;
        };
        // SAFETY: the table is static and stays untouched until its walk ends.
        unsafe { preamble.link_to(table.submit_head()) };

        // Show the frame before this one when this one starts drawing.
        let display = shown;
        shown = fb.begin_deferred_swap();
        present::wait_slot_empty();
        // SAFETY: the slot is empty; the chain (preamble, table, packets,
        // HUD, GP0(1Fh)) is static and not rebuilt before `wait_arena_free`
        // clears its side two frames from now.
        unsafe { present::publish_raw(preamble.head(), display) };
    }
    present::wait_idle();
    psx_io::gpu::write_display_control(shown);
    let vblanks = interrupts::vblank_count().wrapping_sub(start);
    // The presentation cap: no flip within 2 VBlanks of the one before (bucket 7 holds the
    // first flip, which has none).
    let fast: u32 = interrupts::flip_histogram()[..2].iter().sum();
    let after = present::stats();
    let kicks = after.kick_count.wrapping_sub(before.kick_count);
    let skips = after.skip_count.wrapping_sub(before.skip_count);
    let recoveries = after.recovery_count.wrapping_sub(before.recovery_count);

    let checks = [
        (kicks == FRAMES, "queued frames not each kicked once"),
        (recoveries == 0, "present queue stalled"),
        (overflows == 0, "recording overflowed"),
        (vblanks >= FRAMES, "fewer VBlanks than frames"),
        (fast == 0, "a flip came under 2 VBlanks after the last"),
        (interrupts::fault_count() == 0, "exceptions other than IRQs"),
    ];
    let failures = checks.iter().filter(|check| !check.0).count() as u32;
    for (_, what) in checks.iter().filter(|check| !check.0) {
        tty::print("PRESENT-QUEUE check failed: ");
        tty::println(what);
    }
    let lines = [
        line("failures", failures),
        line("frames", FRAMES),
        line("kicks", kicks),
        line("skips", skips),
        line("vblanks", vblanks),
    ];
    let (banner, tint) = if failures == 0 {
        ("PRESENT-QUEUE PASS", GREEN)
    } else {
        ("PRESENT-QUEUE FAIL", RED)
    };
    tty::print(banner);
    for (text, len) in &lines {
        tty::print(" ");
        tty::print(as_str(&text[..*len]));
    }
    tty::println("");

    loop {
        fb.apply_draw_target(&mut gpu);
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "WHOLE FRAMES KICKED AT VBLANK", WHITE);
        font.draw_text(8, 30, banner, tint);
        for (row, (text, len)) in lines.iter().enumerate() {
            font.draw_text(8, 54 + 12 * row as i16, as_str(&text[..*len]), WHITE);
        }
        let mut y = 126;
        for (_, what) in checks.iter().filter(|check| !check.0) {
            font.draw_text(8, y, what, RED);
            y += 12;
        }
        gpu.arm_draw_done();
        gpu.signal_draw_done();
        interrupts::queue_display_control_at_vblank(fb.begin_deferred_swap());
        wait_flip(WAIT_LIMIT);
    }
}

//! `hello-seq` -- plays a cooked song through `psx-seq` and reports what the
//! sequencer cost.
//!
//! The song and its bank are cooked from the player's own cartridge by
//! `psx-seq-cook cook` and are never committed. Point `PSX_SEQ_DIR` at the
//! directory holding `song.psq` and `bank.psqb` when building:
//!
//! ```text
//! PSX_SEQ_DIR=/path/to/cooked cargo build --release ...
//! ```
//!
//! Run headless with `frontend launch --path hello-seq.exe --steps N
//! --dump-audio out.wav` and read the `hello-seq:` lines on the TTY. Every
//! 180 Hz update is timed on root counter 2 (the system clock over 8), so the
//! cost figures are the guest's own.
#![no_std]
#![no_main]

extern crate psx_rt;

use core::ptr::{addr_of_mut, read_volatile, write_volatile};
use psx_rt::tty;
use psx_seq::format::Bank;
use psx_seq::{Sequencer, UPDATE_HZ};
use psx_sfx::hw::Hw;
use psx_sfx::Sample;
use psx_spu::{Adsr, Pitch, Spu, SpuAddr, Voice, Volume, SILENCE_BLOCK};

static SONG: &[u8] = include_bytes!(concat!(env!("PSX_SEQ_DIR"), "/song.psq"));
static BANK: &[u8] = include_bytes!(concat!(env!("PSX_SEQ_DIR"), "/bank.psqb"));

/// Where the bank's ADPCM lands in SPU RAM.
const SPU_BASE: u32 = 0x1010;
/// Voices the music may use.
const VOICES: usize = 20;
/// Seconds of music to run before reporting.
const SECONDS: u32 = 40;

/// The song is patched in place by some sequences, so it lives in RAM.
static mut SONG_RAM: [u8; 16 * 1024] = [0; 16 * 1024];

const T2_COUNTER: *const u32 = (psx_hw::timers::block(2) + psx_hw::timers::COUNTER) as *const u32;
const T2_MODE: *mut u32 = (psx_hw::timers::block(2) + psx_hw::timers::MODE) as *mut u32;
const T2_SYSCLK_DIV8: u32 = 1 << 9;
/// Root counter 2 ticks per second (system clock 33.8688 MHz over 8).
const T2_HZ: u32 = 4_233_600;

fn now() -> u32 {
    // SAFETY: a read of root counter 2's current-value register.
    unsafe { read_volatile(T2_COUNTER) & 0xffff }
}

/// The SPU as [`Hw`]: each method is the register writes it names.
struct SpuHw {
    rate: [u32; 24],
}

impl SpuHw {
    fn pitch_for(&self, voice: u8, pitch_q12: u16) -> Pitch {
        let raw = (self.rate[voice as usize] * pitch_q12 as u32) / 44_100;
        Pitch::raw(raw.clamp(1, 0x3fff) as u16)
    }
}

impl Hw for SpuHw {
    fn configure(&mut self, voice: u8, sample: &Sample, _looped: bool, pitch_q12: u16) {
        let v = Voice::new(voice);
        self.rate[voice as usize] = sample.sample_rate_hz();
        v.set_start_addr(sample.addr());
        // A one-shot parks on the silent block; a loop re-latches this from
        // the loop-start flag in its own data as it plays.
        v.set_loop_addr(SILENCE_BLOCK);
        v.set_adsr(Adsr::default_tone());
        v.set_pitch(self.pitch_for(voice, pitch_q12));
    }

    fn set_volume(&mut self, voice: u8, left: i16, right: i16) {
        Voice::new(voice).set_volume(Volume(left), Volume(right));
    }

    fn set_pitch(&mut self, voice: u8, pitch_q12: u16) {
        Voice::new(voice).set_pitch(self.pitch_for(voice, pitch_q12));
    }

    fn key_on(&mut self, mask: u32) {
        Voice::start(mask);
    }

    fn key_off(&mut self, mask: u32) {
        Voice::release(mask);
    }
}

fn print_dec(mut v: u32) {
    let mut buf = [0u8; 10];
    let mut i = buf.len();
    loop {
        i -= 1;
        buf[i] = b'0' + (v % 10) as u8;
        v /= 10;
        if v == 0 {
            break;
        }
    }
    // SAFETY: ASCII digits.
    tty::print(unsafe { core::str::from_utf8_unchecked(&buf[i..]) });
}

fn line(label: &str, v: u32) {
    tty::print("hello-seq: ");
    tty::print(label);
    tty::print(" ");
    print_dec(v);
    tty::print("\n");
}

#[no_mangle]
fn main() {
    let Some(p) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut spu = Spu::new(p.spu_dma);
    let bank = match Bank::parse(BANK) {
        Ok(b) => b,
        Err(_) => {
            tty::print("hello-seq: bad bank\n");
            return;
        }
    };
    spu.upload_adpcm(SpuAddr::new(SPU_BASE), bank.adpcm());
    line("adpcm bytes", bank.adpcm().len() as u32);

    // SAFETY: single-threaded; this is the only reference to SONG_RAM.
    let ram: &'static mut [u8] =
        unsafe { core::slice::from_raw_parts_mut(addr_of_mut!(SONG_RAM).cast::<u8>(), SONG.len()) };
    ram.copy_from_slice(SONG);

    let mut seq: Sequencer<'_, 1, VOICES> = Sequencer::new((1u32 << VOICES) - 1);
    seq.set_bank(bank, SPU_BASE);
    if seq.start(0, ram).is_err() {
        tty::print("hello-seq: song refused\n");
        return;
    }
    let mut hw = SpuHw { rate: [0; 24] };

    // SAFETY: configure root counter 2 as system clock / 8, free running.
    unsafe { write_volatile(T2_MODE, T2_SYSCLK_DIV8) };
    let per_update = T2_HZ / UPDATE_HZ;
    let mut last = now();
    let mut acc: u32 = 0;
    let mut updates: u32 = 0;
    let total = SECONDS * UPDATE_HZ;
    let (mut spent, mut worst, mut worst_voices) = (0u32, 0u32, 0u32);
    while updates < total {
        let t = now();
        acc += t.wrapping_sub(last) & 0xffff;
        last = t;
        // catch up at most a dozen updates, as `pump` does
        let mut ran = 0;
        while acc >= per_update && ran < 12 {
            acc -= per_update;
            let a = now();
            seq.update(&mut hw);
            let dt = now().wrapping_sub(a) & 0xffff;
            spent += dt;
            worst = worst.max(dt);
            worst_voices = worst_voices.max(seq.voices_in_use());
            updates += 1;
            ran += 1;
        }
        if ran == 12 {
            acc = 0;
        }
    }
    line("updates", updates);
    line("avg cycles per update", spent * 8 / updates);
    line("worst cycles per update", worst * 8);
    line("peak voices", worst_voices);
    line("unsupported ops", seq.unsupported_ops());
    tty::print("hello-seq: done\n");
    loop {}
}

//! `hello-spstack` -- does code run correctly with its stack in the
//! scratchpad while VBlank interrupts keep arriving?
//!
//! A deterministic, stack-heavy workload (three levels of calls, each holding
//! an array in its frame, reading a table kept in the scratchpad below the
//! stack) runs once on the RAM stack and once through
//! `psx_rt::scratchpad::ScratchpadStack::run`, long enough that many VBlank
//! IRQs land while `$sp` is in the scratchpad. The two results must match,
//! the workload must have seen the IRQs from the scratchpad stack, the table
//! and the caller's RAM frame must be intact, and a nested call must run in
//! place. psx-rt's `scratchpad-stack-check` feature is on, so the region's
//! canary and the exception-vector check run around every call too.
//!
//! The verdict goes to the TTY (`SPSTACK PASS ...` or `SPSTACK FAIL ...`)
//! and on screen, so the same disc reads out on a console.
//! `stack-guard` checks the linked call tree fits the region.
//!
//! With the `chained-vector` feature the exception vector jumps to a
//! handler of the example's own that hands straight on to psx-rt's, the
//! way hk-psx's CD wrapper does, declared with
//! `interrupts::declare_stack_safe_handler`; the run must still pass.

#![no_std]
#![no_main]
#![cfg_attr(feature = "chained-vector", feature(asm_experimental_arch))]

extern crate psx_rt;

use core::hint::black_box;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_rt::scratchpad::{self, assert_disjoint, Region, ScratchpadStack};
use psx_rt::{interrupts, tty};
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);
const WHITE: (u8, u8, u8) = (220, 220, 230);
const GREEN: (u8, u8, u8) = (80, 220, 100);
const RED: (u8, u8, u8) = (230, 80, 80);

/// Read by the workload while it runs; must survive the stack below it.
const TABLE: Region = Region::new(0, 256);
/// The workload's stack: everything above the table.
type WorkStack = ScratchpadStack<256, 1024>;
const _: () = assert_disjoint(&[TABLE, WorkStack::REGION]);

const TABLE_WORDS: usize = TABLE.len() / 4;
/// Enough rounds to span a good number of VBlanks.
const ROUNDS: u32 = 96;
/// The scratchpad run must see at least this many IRQs from inside.
const MIN_IRQS_ON_STACK: u32 = 8;

fn table() -> *mut u32 {
    TABLE.addr() as *mut u32
}

fn table_word(i: usize) -> u32 {
    (i as u32).wrapping_mul(0x9e37_79b9) ^ 0x0bad_f00d
}

#[inline(never)]
fn level3(seed: u32) -> u32 {
    let mut local = [0u32; 24];
    for (i, word) in local.iter_mut().enumerate() {
        let t = unsafe {
            table()
                .add((seed as usize + i) % TABLE_WORDS)
                .read_volatile()
        };
        *word = seed.wrapping_mul(0x2545_f491).rotate_left(i as u32) ^ t;
    }
    // Keep the array in the frame: an IRQ between the fill and the fold must
    // not disturb it.
    let local = black_box(&mut local);
    let mut acc = seed;
    for word in local.iter().rev() {
        acc = acc.rotate_left(5) ^ word;
    }
    acc
}

#[inline(never)]
fn level2(seed: u32) -> u32 {
    let mut local = [0u32; 16];
    for (i, word) in local.iter_mut().enumerate() {
        *word = level3(seed ^ (i as u32).wrapping_mul(0x0101_0101));
    }
    let local = black_box(&mut local);
    local
        .iter()
        .fold(seed, |acc, &w| acc.wrapping_mul(31).wrapping_add(w))
}

#[inline(never)]
fn level1(seed: u32) -> u32 {
    let mut local = [0u32; 8];
    for (i, word) in local.iter_mut().enumerate() {
        *word = level2(seed.wrapping_add(i as u32 * 0x1234_5679));
    }
    let local = black_box(&mut local);
    local.iter().fold(seed, |acc, &w| acc.rotate_left(3) ^ w)
}

/// What one run of the workload saw.
#[derive(Clone, Copy, PartialEq, Eq)]
struct Outcome {
    checksum: u32,
    /// VBlanks counted between the workload's first and last instruction.
    irqs: u32,
    /// `$sp` was in the scratchpad on entry and exit.
    on_scratchpad: [bool; 2],
}

#[inline(never)]
fn workload(rounds: u32) -> Outcome {
    let entered = scratchpad::is_on_scratchpad_stack();
    let start = interrupts::vblank_count();
    let mut checksum = 0x1234_5678u32;
    for round in 0..rounds {
        checksum ^= level1(checksum.wrapping_add(round));
    }
    Outcome {
        checksum,
        irqs: interrupts::vblank_count().wrapping_sub(start),
        on_scratchpad: [entered, scratchpad::is_on_scratchpad_stack()],
    }
}

/// `label=XXXXXXXX` for the TTY and the screen.
fn line(label: &str, value: u32) -> ([u8; 32], usize) {
    const DIGITS: &[u8; 16] = b"0123456789ABCDEF";
    let mut text = [b' '; 32];
    let label = &label.as_bytes()[..label.len().min(22)];
    text[..label.len()].copy_from_slice(label);
    text[label.len()] = b'=';
    for i in 0..8 {
        text[label.len() + 1 + i] = DIGITS[(value >> (28 - 4 * i) & 0xf) as usize];
    }
    (text, label.len() + 9)
}

fn as_str(text: &[u8]) -> &str {
    core::str::from_utf8(text).unwrap_or("?")
}

// A handler of the game's own in the vector: it leaves $sp alone and
// chains to psx-rt's.
#[cfg(feature = "chained-vector")]
core::arch::global_asm!(
    ".set noreorder",
    ".section .text.hello_spstack_vector",
    ".globl hello_spstack_vector",
    "hello_spstack_vector:",
    "j __psx_rt_exception_handler",
    "nop",
    ".set reorder"
);

#[cfg(feature = "chained-vector")]
extern "C" {
    fn hello_spstack_vector();
}

#[no_mangle]
fn main() {
    interrupts::install_vblank_counter();
    #[cfg(feature = "chained-vector")]
    // SAFETY: the vector is one `j` and a nop; the handler touches no
    // register but psx-rt's own $k0/$k1.
    unsafe {
        let handler = hello_spstack_vector as *const () as usize as u32;
        (0x8000_0080 as *mut u32).write_volatile(0x0800_0000 | ((handler >> 2) & 0x03ff_ffff));
        (0x8000_0084 as *mut u32).write_volatile(0);
        psx_rt::cache::flush_instruction_cache();
        interrupts::declare_stack_safe_handler(hello_spstack_vector);
    }
    for i in 0..TABLE_WORDS {
        unsafe { table().add(i).write_volatile(table_word(i)) };
    }
    // A RAM frame the scratchpad run must leave alone.
    let ram_frame = black_box([0xa5a5_0000u32 | 0x1111, 0x2222, 0x3333, 0x4444]);

    let ram = workload(black_box(ROUNDS));

    #[cfg(feature = "panic-on-stack")]
    unsafe {
        WorkStack::run::<(), _>(|| {
            if level1(black_box(1)) != 0 {
                panic!("deliberate panic on the scratchpad stack");
            }
        })
    };

    let start = interrupts::vblank_count();
    let mut nested = [false; 2];
    let spad = unsafe {
        WorkStack::run(|| {
            // A nested call runs in place, still on the scratchpad.
            nested = WorkStack::run(|| [scratchpad::is_on_scratchpad_stack(), true]);
            workload(black_box(ROUNDS))
        })
    };
    let spad_vblanks = interrupts::vblank_count().wrapping_sub(start);

    let checks = [
        (ram.checksum == spad.checksum, "checksums differ"),
        (
            ram.on_scratchpad == [false, false],
            "RAM run saw the scratchpad",
        ),
        (
            spad.on_scratchpad == [true, true],
            "run did not use the scratchpad",
        ),
        (
            spad.irqs >= MIN_IRQS_ON_STACK,
            "too few IRQs on the scratchpad stack",
        ),
        (nested == [true, true], "nested run did not run in place"),
        (!scratchpad::is_on_scratchpad_stack(), "$sp not restored"),
        (
            black_box(ram_frame) == [0xa5a5_1111, 0x2222, 0x3333, 0x4444],
            "RAM frame changed",
        ),
        (
            (0..TABLE_WORDS).all(|i| unsafe { table().add(i).read_volatile() } == table_word(i)),
            "table below the stack changed",
        ),
        (interrupts::fault_count() == 0, "exceptions other than IRQs"),
    ];
    let failures = checks.iter().filter(|check| !check.0).count() as u32;
    for (_, what) in checks.iter().filter(|check| !check.0) {
        tty::print("SPSTACK check failed: ");
        tty::println(what);
    }
    let lines = [
        line("failures", failures),
        line("checksum", spad.checksum),
        line("irqs_on_stack", spad.irqs),
        line("vblanks_ram", ram.irqs),
        line("vblanks_spad", spad_vblanks),
    ];
    let (banner, tint) = if failures == 0 {
        ("SPSTACK PASS", GREEN)
    } else {
        ("SPSTACK FAIL", RED)
    };
    tty::print(banner);
    for (text, len) in &lines {
        tty::print(" ");
        tty::print(as_str(&text[..*len]));
    }
    tty::println("");

    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);
    loop {
        fb.clear(&mut gpu, (10, 12, 20));
        font.draw_text(8, 6, "SCRATCHPAD STACK UNDER VBLANK IRQS", WHITE);
        font.draw_text(8, 30, banner, tint);
        for (row, (text, len)) in lines.iter().enumerate() {
            font.draw_text(8, 54 + 12 * row as i16, as_str(&text[..*len]), WHITE);
        }
        let mut y = 126;
        for (_, what) in checks.iter().filter(|check| !check.0) {
            font.draw_text(8, y, what, RED);
            y += 12;
        }
        gpu.wait_idle();
        interrupts::wait_vblank();
        fb.swap(&mut gpu);
    }
}

