//! `hello-tex` -- upload two 4bpp CLUT textures cooked from source
//! photographs (a brick wall + a cobblestone floor, produced by
//! `psxed tex` from their `vendor/*.jpg` originals) and draw them
//! as animated bouncing sprites.
//!
//! Exercises the full host-side + runtime texture pipeline:
//!
//!   editor `psxed tex`       host: PNG/JPG → crop → resample →
//!                             median-cut quantise → pack 4bpp →
//!                             `.psxt` blob
//!
//!   `include_bytes!`         compile: blob embedded in the MIPS
//!                             binary, no runtime disc IO needed
//!
//!   `Texture::from_bytes`    runtime: zero-copy header parse,
//!                             two slices (pixels + CLUT)
//!
//!   `upload_bytes`           runtime: pixels + CLUT to VRAM via
//!                             GP0 0xA0, once per texture + CLUT
//!
//!   GP0 0x64                 runtime: textured-rect primitive
//!                             samples the tpage + CLUT
//!
//! Two sprites bouncing at different speeds prove that multiple
//! cooked textures can share a tpage and each hits its own CLUT.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_asset::Texture;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_hw::gpu::{pack_color, pack_texcoord, pack_vertex, pack_xy};
use psx_io::gpu::{wait_command_ready, write_command};
use psx_math::sincos;
use psx_vram::{upload_bytes, Clut, TextureDepth, TexturePage, TextureWindowAtlas, VramRect};

/// Wall (brick) -- cooked by `make assets` from
/// `vendor/brick-wall.jpg`.
static BRICK_BLOB: &[u8] = include_bytes!("../../../../assets/textures/brick-wall.psxt");

/// Floor (cobblestone / batako) -- cooked from `vendor/floor.jpg`.
static FLOOR_BLOB: &[u8] = include_bytes!("../../../../assets/textures/floor.psxt");

/// Shared tpage -- both 64-texel-wide 4bpp textures fit in one
/// 256-wide tpage with room to spare. The `apply_as_draw_mode`
/// call at startup sets this as the current tpage; every textured
/// sprite we draw samples from it.
const SHARED_TPAGE: TexturePage = TexturePage::new(640, 0, TextureDepth::Bit4);

/// CLUT for the brick texture. X aligned to 16; Y=480 sits below
/// both framebuffer halves (0..240 and 240..480).
const BRICK_CLUT: Clut = Clut::new(0, 480);

/// CLUT for the floor texture. One row down -- 16 halfwords ≠ a
/// full VRAM row width, so we just step Y by 1 to keep CLUTs
/// compact.
const FLOOR_CLUT: Clut = Clut::new(0, 481);

/// Both textures are 64×64. The floor sits at U=64 inside the
/// tpage, offset from the brick at U=0.
const TEX_W: u16 = 64;
const TEX_H: u16 = 64;

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));

    // --- Parse + upload both cooked textures ---
    let brick = Texture::from_bytes(BRICK_BLOB).expect("brick.psxt");
    let floor = Texture::from_bytes(FLOOR_BLOB).expect("floor.psxt");
    // Restrict allocations to the first 224 texel rows. A page at Y=256
    // can use this same bound to leave physical rows 480..512 for CLUTs.
    let mut atlas = TextureWindowAtlas::<1>::new();
    let brick_slot = atlas
        .allocate_with_usable_rows(TEX_W, TEX_H, 224)
        .expect("brick slot");
    let floor_slot = atlas
        .allocate_with_usable_rows(TEX_W, TEX_H, 224)
        .expect("floor slot");

    // Brick occupies the left 16 halfwords of the tpage (U 0..64).
    // VRAM rect width is in HALFWORDS -- 4 texels per halfword at
    // 4bpp -- so 64 texels wide = 16 halfwords wide.
    let brick_pix_rect = VramRect::new(
        SHARED_TPAGE.x() + u16::from(brick_slot.origin_u()) / 4,
        SHARED_TPAGE.y() + u16::from(brick_slot.origin_v()),
        brick.halfwords_per_row(),
        brick.height(),
    );
    upload_bytes(brick_pix_rect, brick.pixel_bytes());
    let brick_clut_rect = VramRect::new(BRICK_CLUT.x(), BRICK_CLUT.y(), brick.clut_entries(), 1);
    upload_bytes(brick_clut_rect, brick.clut_bytes());

    // Floor slotted right next to the brick, still in the same
    // tpage. X offset = brick's halfword count.
    let floor_pix_rect = VramRect::new(
        SHARED_TPAGE.x() + u16::from(floor_slot.origin_u()) / 4,
        SHARED_TPAGE.y() + u16::from(floor_slot.origin_v()),
        floor.halfwords_per_row(),
        floor.height(),
    );
    upload_bytes(floor_pix_rect, floor.pixel_bytes());
    let floor_clut_rect = VramRect::new(FLOOR_CLUT.x(), FLOOR_CLUT.y(), floor.clut_entries(), 1);
    upload_bytes(floor_clut_rect, floor.clut_bytes());

    // --- Pre-encode the per-texture UV words ---
    SHARED_TPAGE.apply_as_draw_mode();
    let brick_clut_word = BRICK_CLUT.uv_word();
    let floor_clut_word = FLOOR_CLUT.uv_word();

    // Sine-oscillating centres -- same Q0.12 phase pattern as
    // hello-ot's triangles. Modulo arithmetic would create a
    // sawtooth snap-back every N frames; `sincos::sin_q12`
    // gives a smooth back-and-forth drift.
    let mut frame: u32 = 0;
    loop {
        fb.clear(&mut gpu, (16, 16, 32));

        // Brick in the upper half: anchor at (100, 40), drifts
        // horizontally ±80 px and vertically ±20 px at slightly
        // different rates so the motion is a Lissajous curve.
        let brick_phase_x = (frame.wrapping_mul(48) & 0xfff) as u16;
        let brick_phase_y = (frame.wrapping_mul(64) & 0xfff) as u16;
        let bx = 100 + drift(brick_phase_x, 80);
        let by = 40 + drift(brick_phase_y, 20);
        draw_sprite(
            bx,
            by,
            TEX_W,
            TEX_H,
            (brick_slot.origin_u(), brick_slot.origin_v()),
            brick_clut_word,
        );

        // Floor in the lower half: faster, opposite phase, so the
        // two sprites cross each other without colliding.
        let floor_phase_x = (frame.wrapping_mul(72).wrapping_add(2048) & 0xfff) as u16;
        let floor_phase_y = (frame.wrapping_mul(56).wrapping_add(1024) & 0xfff) as u16;
        let fx = 160 + drift(floor_phase_x, 80);
        let fy = 140 + drift(floor_phase_y, 20);
        draw_sprite(
            fx,
            fy,
            TEX_W,
            TEX_H,
            (floor_slot.origin_u(), floor_slot.origin_v()),
            floor_clut_word,
        );

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);
        frame = frame.wrapping_add(1);
    }
}

/// Pixel displacement from a Q0.12 phase. `sin_q12` returns Q1.12
/// in `[-0x1000, 0x1000]`; multiplying by `amp_px` and shifting 12
/// rescales back to pixels -- smooth ±`amp_px` drift with no
/// sawtooth wrap.
#[inline]
fn drift(phase_q12: u16, amp_px: i16) -> i16 {
    ((sincos::sin_q12(phase_q12) * amp_px as i32) >> 12) as i16
}

/// Issue GP0 0x64 (variable-size textured rectangle) with the
/// 4-word packet. Tint `(0x80, 0x80, 0x80)` passes texels through
/// unmodulated.
fn draw_sprite(x: i16, y: i16, w: u16, h: u16, uv: (u8, u8), clut: u16) {
    wait_command_ready();
    write_command(psx_hw::gpu::packet::TEXTURED_RECT | pack_color(0x80, 0x80, 0x80));
    write_command(pack_vertex(x, y));
    write_command(pack_texcoord(uv.0, uv.1, clut));
    write_command(pack_xy(w, h));
}

//! `hello-tri` -- the smallest interesting PSoXide homebrew.
//!
//! Initialises the GPU, clears the framebuffer to dark blue, and
//! draws one Gouraud-shaded triangle per frame with a slight
//! time-based wobble so you can tell the render loop is alive.
//!
//! Running it end-to-end proves:
//! - The PSX-EXE loader correctly seeded PC / SP / GP.
//! - `_start` cleared BSS and reached `main()`.
//! - The GPU's GP1 commands configure the display.
//! - Triangle rasterisation + vsync behave.

#![no_std]
#![no_main]

// Pull psx-rt in so the linker keeps `_start`, the panic handler,
// and (if enabled) the heap allocator; a plain dependency doesn't
// force the link because we don't call anything from it.
extern crate psx_rt;

use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::prim::TriGouraud;
use psx_gpu::Gpu;
use psx_rt::tty;

#[no_mangle]
fn main() {
    tty::println("hello-tri: booted via HLE BIOS");

    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );

    // Double-buffer: buffer A at VRAM (0, 0), buffer B at (0, 240).
    // The TV always scans out a stable completed frame while we
    // draw into the other buffer. PS1 games do this universally --
    // workload-light demos like this one wouldn't flicker even
    // single-buffered, but adopting the pattern here keeps every
    // example on the same footing.
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    // Bootstrap draw-area / offset to the first back buffer (A).
    // `DoubleBuffer::swap` re-applies them every flip.
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));

    tty::println("hello-tri: entering render loop");
    let mut frame: u16 = 0;
    loop {
        // Clear the back buffer (the one we're about to draw into).
        fb.clear(&mut gpu, (0, 0, 64));

        // Wobble the triangle: ±30 px vertical bounce.
        let wobble = (((frame % 60) as i16) - 30).abs();
        let verts = [(160, 40 + wobble), (60, 200 - wobble), (260, 200 - wobble)];
        gpu.draw(&TriGouraud::new(
            verts,
            [(255, 64, 64), (64, 255, 64), (64, 64, 255)],
        ));

        gpu.wait_idle();
        psx_rt::interrupts::wait_vblank();
        fb.swap(&mut gpu);

        frame = frame.wrapping_add(1);
    }
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! `hello-wide` -- every `psx_math::Wide` / `WideU` / `Mask64` operation, run
//! on the target against a reference built from 32-bit arithmetic only.
//!
//! Two jobs:
//!
//! 1. Prove the operations compute the right answer on the R3000 (edge values
//!    and a fixed pseudo-random stream; the verdict goes to the TTY as
//!    `WIDE PASS` / `WIDE FAIL`).
//! 2. Prove they link no compiler helper: the image is built with a link map
//!    and `tools/guest_symbol_gate.sh` must pass on it (the gate fails on
//!    `__divdi3`, `__udivdi3`, `__moddi3`, `__umoddi3`, `__muldi3`, the 64-bit
//!    shift helpers, `u64_div_rem`, the 128-bit helpers and soft-float).
//!
//! Nothing here names `i64` or `u64`. Operands go through `black_box`, so
//! nothing const-folds and every operation is real code.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::cmp::Ordering;
use core::hint::black_box;
use psx_math::{Mask64, Wide, WideU};
use psx_rt::tty;

/// A 64-bit value as two words, with just enough 32-bit arithmetic to check
/// the library: the reference.
#[derive(Clone, Copy, PartialEq, Eq)]
struct R {
    hi: u32,
    lo: u32,
}

impl R {
    const fn new(hi: u32, lo: u32) -> R {
        R { hi, lo }
    }
    fn of(a: i32) -> R {
        R::new(if a < 0 { u32::MAX } else { 0 }, a as u32)
    }
    fn add(self, o: R) -> R {
        let lo = self.lo.wrapping_add(o.lo);
        let carry = (lo < self.lo) as u32;
        R::new(self.hi.wrapping_add(o.hi).wrapping_add(carry), lo)
    }
    fn neg(self) -> R {
        R::new(!self.hi, !self.lo).add(R::new(0, 1))
    }
    fn sub(self, o: R) -> R {
        self.add(o.neg())
    }
    fn is_neg(self) -> bool {
        self.hi >> 31 != 0
    }
    fn abs(self) -> R {
        if self.is_neg() {
            self.neg()
        } else {
            self
        }
    }
    /// The full unsigned product of two words, from 16-bit limbs.
    fn mulu(a: u32, b: u32) -> R {
        let (a0, a1, b0, b1) = (a & 0xffff, a >> 16, b & 0xffff, b >> 16);
        let (p00, p01, p10, p11) = (a0 * b0, a0 * b1, a1 * b0, a1 * b1);
        let mid = (p00 >> 16) + (p01 & 0xffff) + (p10 & 0xffff);
        R::new(
            p11 + (p01 >> 16) + (p10 >> 16) + (mid >> 16),
            (p00 & 0xffff) | (mid << 16),
        )
    }
    /// The full signed product of two words.
    fn muls(a: i32, b: i32) -> R {
        let p = R::mulu(a as u32, b as u32);
        let mut hi = p.hi;
        if a < 0 {
            hi = hi.wrapping_sub(b as u32);
        }
        if b < 0 {
            hi = hi.wrapping_sub(a as u32);
        }
        R::new(hi, p.lo)
    }
    /// The low 64 bits of the product of two 64-bit values.
    fn mul_low(self, o: R) -> R {
        let p = R::mulu(self.lo, o.lo);
        R::new(
            p.hi.wrapping_add(self.lo.wrapping_mul(o.hi))
                .wrapping_add(self.hi.wrapping_mul(o.lo)),
            p.lo,
        )
    }
    fn shl(self, n: u32) -> R {
        let n = n & 63;
        if n == 0 {
            self
        } else if n < 32 {
            R::new((self.hi << n) | (self.lo >> (32 - n)), self.lo << n)
        } else {
            R::new(self.lo << (n - 32), 0)
        }
    }
    /// Shift right; `fill` is the word shifted in (0, or all ones to keep a sign).
    fn shr(self, n: u32, fill: u32) -> R {
        let n = n & 63;
        if n == 0 {
            self
        } else if n < 32 {
            R::new(
                (self.hi >> n) | (fill << (32 - n)),
                (self.lo >> n) | (self.hi << (32 - n)),
            )
        } else if n == 32 {
            R::new(fill, self.hi)
        } else {
            R::new(fill, (self.hi >> (n - 32)) | (fill << (64 - n)))
        }
    }
    fn sar(self, n: u32) -> R {
        self.shr(n, if self.is_neg() { u32::MAX } else { 0 })
    }
    fn cmp_signed(self, o: R) -> Ordering {
        (self.hi as i32)
            .cmp(&(o.hi as i32))
            .then(self.lo.cmp(&o.lo))
    }
    fn cmp_unsigned(self, o: R) -> Ordering {
        self.hi.cmp(&o.hi).then(self.lo.cmp(&o.lo))
    }
}

/// xorshift32, the same stream on every run.
struct Rng(u32);

impl Rng {
    fn next(&mut self) -> u32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.0 = x;
        x
    }
    /// A word of random magnitude, so small, Q12-sized and full-range values all occur.
    fn word(&mut self) -> u32 {
        let v = self.next();
        let w = self.next();
        match v & 3 {
            0 => w,
            1 => ((w as i32) >> 16) as u32,
            2 => ((w as i32) >> 8) as u32,
            _ => ((w as i32) >> 24) as u32,
        }
    }
    fn wide(&mut self) -> R {
        let v = self.next();
        let (hi, lo) = (self.word(), self.next());
        match v & 3 {
            0 => R::new(hi, lo),
            1 => R::of(self.word() as i32),
            2 => R::new(hi >> 12, lo),
            _ => R::new(hi >> 28, lo),
        }
    }
}

struct Run {
    cases: u32,
    failures: u32,
}

impl Run {
    fn check(&mut self, name: &str, ok: bool) {
        self.cases += 1;
        if !ok {
            self.failures += 1;
            if self.failures <= 16 {
                tty::print("  FAIL ");
                tty::println(name);
            }
        }
    }
    fn wide(&mut self, name: &str, got: Wide, want: R) {
        self.check(
            name,
            got.high() as u32 == want.hi && got.low_u32() == want.lo,
        );
    }
    fn wide_u(&mut self, name: &str, got: WideU, want: R) {
        self.check(name, got.high() == want.hi && got.low() == want.lo);
    }
}

fn to_wide(r: R) -> Wide {
    Wide::from_parts(black_box(r.hi) as i32, black_box(r.lo))
}

fn to_wide_u(r: R) -> WideU {
    WideU::from_parts(black_box(r.hi), black_box(r.lo))
}

const EDGE_WORDS: [u32; 16] = [
    0,
    1,
    2,
    4095,
    4096,
    0xffff,
    0x1_0000,
    0x7fff_ffff,
    0x8000_0000,
    0x8000_0001,
    0xffff_f000,
    0xffff_ffff,
    0xffff_fffe,
    0x1234_5678,
    0xdead_beef,
    0xffff_0000,
];

/// Every value the checks run through: the edge words as both halves, and a
/// run of random ones.
fn wide_values(rng: &mut Rng, out: &mut [R; 320]) {
    let mut n = 0;
    for &hi in &EDGE_WORDS[..8] {
        for &lo in &EDGE_WORDS {
            out[n] = R::new(hi, lo);
            n += 1;
        }
    }
    for &hi in &EDGE_WORDS[8..] {
        for &lo in &EDGE_WORDS[..8] {
            out[n] = R::new(hi, lo);
            n += 1;
        }
    }
    while n < out.len() {
        out[n] = rng.wide();
        n += 1;
    }
}

fn products(run: &mut Run, rng: &mut Rng) {
    for i in 0..EDGE_WORDS.len() * EDGE_WORDS.len() + 3000 {
        let (a, b) = if i < EDGE_WORDS.len() * EDGE_WORDS.len() {
            (
                EDGE_WORDS[i / EDGE_WORDS.len()],
                EDGE_WORDS[i % EDGE_WORDS.len()],
            )
        } else {
            (rng.word(), rng.word())
        };
        let (sa, sb) = (black_box(a) as i32, black_box(b) as i32);
        let acc = rng.wide();
        let p = R::muls(sa, sb);
        run.wide("mul", Wide::mul(sa, sb), p);
        run.wide("mul_add", to_wide(acc).mul_add(sa, sb), acc.add(p));
        run.wide("mul_sub", to_wide(acc).mul_sub(sa, sb), acc.sub(p));
        run.wide("of", Wide::of(sa), R::of(sa));
        run.wide("of_u", Wide::of_u(black_box(a)), R::new(0, a));
        run.wide(
            "from_parts",
            Wide::from_parts(sa, black_box(b)),
            R::new(a, b),
        );
        let pu = R::mulu(a, b);
        run.wide_u("mulu", WideU::mul(black_box(a), black_box(b)), pu);
        run.wide_u(
            "mulu_add",
            to_wide_u(acc).mul_add(black_box(a), black_box(b)),
            acc.add(pu),
        );
        run.wide_u("of_unsigned", WideU::of(black_box(a)), R::new(0, a));
    }
    let v = [black_box(3), black_box(-4096), black_box(i32::MIN)];
    let w = [black_box(i32::MAX), black_box(7), black_box(i32::MIN)];
    let want = R::muls(v[0], w[0])
        .add(R::muls(v[1], w[1]))
        .add(R::muls(v[2], w[2]));
    run.wide("dot3", Wide::dot3(v, w), want);
}

fn arithmetic(run: &mut Run, values: &[R; 320]) {
    for (i, &a) in values.iter().enumerate() {
        let wa = to_wide(a);
        run.wide("neg", -wa, a.neg());
        run.wide("negate", wa.negate(), a.neg());
        run.wide("abs", wa.abs(), a.abs());
        run.check("is_negative", wa.is_negative() == a.is_neg());
        run.check(
            "is_positive",
            wa.is_positive() == (!a.is_neg() && (a.hi | a.lo) != 0),
        );
        run.check("is_zero", wa.is_zero() == (a.hi | a.lo == 0));
        run.check("low", wa.low() == a.lo as i32 && wa.low_u32() == a.lo);
        run.check("high", wa.high() as u32 == a.hi);
        let wu = to_wide_u(a);
        run.check("wide_u low/high", wu.low() == a.lo && wu.high() == a.hi);
        run.check("wide_u is_zero", wu.is_zero() == (a.hi | a.lo == 0));
        // 15 partners per value keeps the pair count bounded.
        for j in 0..15 {
            let b = values[(i * 7 + j * 19 + 1) % values.len()];
            let wb = to_wide(b);
            run.wide("add", wa + wb, a.add(b));
            run.wide("sub", wa - wb, a.sub(b));
            run.wide("add_w", wa.add_w(wb), a.add(b));
            run.wide("sub_w", wa.sub_w(wb), a.sub(b));
            run.wide("mul_w", wa.mul_w(wb), a.mul_low(b));
            run.check("cmp", wa.cmp(&wb) == a.cmp_signed(b));
            run.check("lt/ge", (wa < wb) == (a.cmp_signed(b) == Ordering::Less));
            run.check(
                "max",
                wa.max(wb)
                    == if a.cmp_signed(b) == Ordering::Less {
                        wb
                    } else {
                        wa
                    },
            );
            run.check(
                "min",
                wa.min(wb)
                    == if a.cmp_signed(b) == Ordering::Greater {
                        wb
                    } else {
                        wa
                    },
            );
            let (ua, ub) = (to_wide_u(a), to_wide_u(b));
            run.wide_u("wide_u add", ua + ub, a.add(b));
            run.wide_u("wide_u sub", ua - ub, a.sub(b));
            run.wide_u("wide_u add()", WideU::add(ua, ub), a.add(b));
            run.wide_u("wide_u sub()", WideU::sub(ua, ub), a.sub(b));
            let sum = a.add(b);
            let overflow = R::cmp_unsigned(sum, a) == Ordering::Less;
            run.wide_u(
                "wide_u saturating_add",
                ua.saturating_add(ub),
                if overflow {
                    R::new(u32::MAX, u32::MAX)
                } else {
                    sum
                },
            );
            run.check("wide_u cmp", ua.cmp(&ub) == a.cmp_unsigned(b));
        }
        for &k in &EDGE_WORDS {
            let k = black_box(k) as i32;
            run.wide("times", wa.times(k), a.mul_low(R::of(k)));
            run.wide("plus", wa.plus(k), a.add(R::of(k)));
            run.check("cmp_i32", wa.cmp_i32(k) == a.cmp_signed(R::of(k)));
            run.wide_u(
                "wide_u times",
                wu.times(k as u32),
                a.mul_low(R::new(0, k as u32)),
            );
        }
    }
}

fn shifts(run: &mut Run, values: &[R; 320]) {
    for &a in values.iter().step_by(3) {
        let (wa, wu) = (to_wide(a), to_wide_u(a));
        // Every count 0..64 plus counts past 64 (taken modulo 64).
        for n in 0..72u32 {
            let n = black_box(n);
            run.wide("sar", wa.sar(n), a.sar(n));
            run.wide(">>", wa >> n, a.sar(n));
            run.wide("shl_by", wa.shl_by(n), a.shl(n));
            run.wide("<<", wa << n, a.shl(n));
            run.wide("lshr", wa.lshr(n), a.shr(n, 0));
            run.check("shr_i32", wa.shr_i32(n) == a.sar(n).lo as i32);
            run.wide_u("wide_u >>", wu >> n, a.shr(n, 0));
            run.wide_u("wide_u <<", wu << n, a.shl(n));
            run.wide_u("wide_u shr_by", wu.shr_by(n), a.shr(n, 0));
            run.wide_u("wide_u shl_by", wu.shl_by(n), a.shl(n));
            run.check("wide_u shr_u32", wu.shr_u32(n) == a.shr(n, 0).lo);
        }
    }
}

fn extraction(run: &mut Run, values: &[R; 320]) {
    for &a in values {
        let (wa, wu) = (to_wide(a), to_wide_u(a));
        let fits_i32 = a.hi == (a.lo as i32 >> 31) as u32;
        run.check(
            "to_i32",
            wa.to_i32() == if fits_i32 { Some(a.lo as i32) } else { None },
        );
        let sat = if fits_i32 {
            a.lo as i32
        } else if a.is_neg() {
            i32::MIN
        } else {
            i32::MAX
        };
        run.check("saturate_i32", wa.saturate_i32() == sat);
        let fits_u32 = a.hi == 0;
        run.check(
            "to_u32",
            wa.to_u32() == if fits_u32 { Some(a.lo) } else { None },
        );
        let sat_u = if a.is_neg() {
            0
        } else if a.hi != 0 {
            u32::MAX
        } else {
            a.lo
        };
        run.check("saturate_u32", wa.saturate_u32() == sat_u);
        run.check(
            "wide_u to_u32",
            wu.to_u32() == if fits_u32 { Some(a.lo) } else { None },
        );
        run.check(
            "wide_u saturate_u32",
            wu.saturate_u32() == if a.hi != 0 { u32::MAX } else { a.lo },
        );
    }
}

fn roots(run: &mut Run, values: &[R; 320]) {
    for &a in values {
        // The floor root r satisfies r*r <= v < (r+1)*(r+1) (r+1 is 2^32 at the top).
        let unsigned_root = to_wide_u(a).isqrt();
        let square = R::mulu(unsigned_root, unsigned_root);
        let below = R::cmp_unsigned(square, a) != Ordering::Greater;
        let next = R::mulu(unsigned_root.wrapping_add(1), unsigned_root.wrapping_add(1));
        let above = unsigned_root == u32::MAX || R::cmp_unsigned(next, a) == Ordering::Greater;
        run.check("wide_u isqrt", below && above);
        let signed_root = to_wide(a).isqrt();
        if a.is_neg() || (a.hi | a.lo) == 0 {
            run.check("isqrt of <= 0", signed_root == 0);
        } else {
            run.check("isqrt", signed_root == unsigned_root);
        }
    }
    run.check(
        "isqrt 13",
        Wide::dot3(black_box([3, 4, 12]), [3, 4, 12]).isqrt() == 13,
    );
}

fn masks(run: &mut Run, rng: &mut Rng) {
    let mut mask = black_box(Mask64::EMPTY);
    let (mut lo, mut hi) = (0u32, 0u32);
    for _ in 0..2000 {
        let bit = (rng.next() % 64) as usize;
        let on = rng.next() & 1 != 0;
        let word = if bit < 32 { &mut lo } else { &mut hi };
        match rng.next() % 3 {
            0 if on => {
                mask.set(bit);
                *word |= 1 << (bit & 31);
            }
            1 => {
                mask.clear(bit);
                *word &= !(1 << (bit & 31));
            }
            _ => {
                mask.assign(bit, on);
                if on {
                    *word |= 1 << (bit & 31);
                } else {
                    *word &= !(1 << (bit & 31));
                }
            }
        }
        let probe = (rng.next() % 72) as usize;
        let want = probe < 64 && (if probe < 32 { lo } else { hi }) >> (probe & 31) & 1 != 0;
        run.check("mask test", mask.test(probe) == want);
    }
}

#[no_mangle]
fn main() {
    let mut run = Run {
        cases: 0,
        failures: 0,
    };
    let mut rng = Rng(0x9e37_79b9);
    let mut values = [R::new(0, 0); 320];
    wide_values(&mut rng, &mut values);
    products(&mut run, &mut rng);
    arithmetic(&mut run, &values);
    shifts(&mut run, &values);
    extraction(&mut run, &values);
    roots(&mut run, &values);
    masks(&mut run, &mut rng);
    if run.failures == 0 {
        tty::print("WIDE PASS cases=");
        tty::print_hex_u32(run.cases);
    } else {
        tty::print("WIDE FAIL failures=");
        tty::print_hex_u32(run.failures);
        tty::print(" of=");
        tty::print_hex_u32(run.cases);
    }
    tty::println("");
    tty::println("WIDE DONE");
    loop {}
}

// SPDX-License-Identifier: GPL-2.0-or-later
//! `hello-wide-div` -- every `psx_math::wide_div` operation (division of a `Wide` /
//! `WideU`), run on the target against a reference built from 32-bit arithmetic only,
//! then timed.
//!
//! Three jobs:
//!
//! 1. Prove the operations compute the right answer on the R3000: edge values and a
//!    fixed pseudo-random stream, against a bit-by-bit restoring division over 32-bit
//!    words (the verdict goes to the TTY as `WIDEDIV PASS` / `WIDEDIV FAIL`).
//! 2. Prove they link no compiler helper: the image is built with a link map and
//!    `tools/guest_symbol_gate.sh` must pass on it, with no opt-out.
//! 3. Print the cost of each operation in CPU cycles (`widediv: <op> cycles_per_call=N`)
//!    from root counter 2, with the input shuffling subtracted. The figures are what the
//!    table in the `psx-math` README quotes.
//!
//! Nothing here names `i64` or `u64`. Operands go through `black_box`, so nothing
//! const-folds and every operation is real code.

#![no_std]
#![no_main]

extern crate psx_rt;

use core::cmp::Ordering;
use core::hint::black_box;
use core::ptr::{read_volatile, write_volatile};
use psx_math::{Rounding, Wide, WideU};
use psx_rt::tty;

/// A 64-bit value as two words, with just enough 32-bit arithmetic to check the library.
#[derive(Clone, Copy, PartialEq, Eq)]
struct R {
    hi: u32,
    lo: u32,
}

impl R {
    const fn new(hi: u32, lo: u32) -> R {
        R { hi, lo }
    }
    fn of(a: i32) -> R {
        R::new(if a < 0 { u32::MAX } else { 0 }, a as u32)
    }
    fn add(self, o: R) -> R {
        let lo = self.lo.wrapping_add(o.lo);
        let carry = (lo < self.lo) as u32;
        R::new(self.hi.wrapping_add(o.hi).wrapping_add(carry), lo)
    }
    fn neg(self) -> R {
        R::new(!self.hi, !self.lo).add(R::new(0, 1))
    }
    fn sub(self, o: R) -> R {
        self.add(o.neg())
    }
    fn is_neg(self) -> bool {
        self.hi >> 31 != 0
    }
    fn is_zero(self) -> bool {
        self.hi | self.lo == 0
    }
    fn abs(self) -> R {
        if self.is_neg() {
            self.neg()
        } else {
            self
        }
    }
    fn cmp(self, o: R) -> Ordering {
        self.hi.cmp(&o.hi).then(self.lo.cmp(&o.lo))
    }
    /// The full unsigned product of two words, from 16-bit limbs.
    fn mulu(a: u32, b: u32) -> R {
        let (a0, a1, b0, b1) = (a & 0xffff, a >> 16, b & 0xffff, b >> 16);
        let (p00, p01, p10, p11) = (a0 * b0, a0 * b1, a1 * b0, a1 * b1);
        let mid = (p00 >> 16) + (p01 & 0xffff) + (p10 & 0xffff);
        R::new(
            p11 + (p01 >> 16) + (p10 >> 16) + (mid >> 16),
            (p00 & 0xffff) | (mid << 16),
        )
    }
}

/// The exact 128-bit product of two unsigned 64-bit values, as four words, low first.
fn mul_full(a: R, b: R) -> [u32; 4] {
    let (p00, p01, p10, p11) = (
        R::mulu(a.lo, b.lo),
        R::mulu(a.lo, b.hi),
        R::mulu(a.hi, b.lo),
        R::mulu(a.hi, b.hi),
    );
    // Column sums with carries, in R so no 32-bit add can wrap unseen.
    let c1 = R::new(0, p00.hi)
        .add(R::new(0, p01.lo))
        .add(R::new(0, p10.lo));
    let c2 = R::new(0, p01.hi)
        .add(R::new(0, p10.hi))
        .add(R::new(0, p11.lo))
        .add(R::new(0, c1.hi));
    let w3 = p11.hi.wrapping_add(c2.hi);
    [p00.lo, c1.lo, c2.lo, w3]
}

fn cmp_words(a: [u32; 4], b: [u32; 4]) -> Ordering {
    for i in (0..4).rev() {
        let c = a[i].cmp(&b[i]);
        if c != Ordering::Equal {
            return c;
        }
    }
    Ordering::Equal
}

/// Restoring long division of a numerator of `bits` bits (words low first) by a nonzero
/// 64-bit divisor: quotient words and the remainder. One bit at a time, 32-bit only.
fn udivrem(n: [u32; 4], d: R, bits: usize) -> ([u32; 4], R) {
    let mut q = [0u32; 4];
    let mut r = R::new(0, 0);
    for i in (0..bits).rev() {
        let carry = r.hi >> 31;
        r = R::new(
            (r.hi << 1) | (r.lo >> 31),
            (r.lo << 1) | ((n[i / 32] >> (i % 32)) & 1),
        );
        if carry != 0 || r.cmp(d) != Ordering::Less {
            r = r.sub(d);
            q[i / 32] |= 1 << (i % 32);
        }
    }
    (q, r)
}

/// The signed quotient of `n / d` rounded as asked: its sign and magnitude (a 64-bit
/// value; the quotient of two 64-bit values always fits).
fn signed_quotient(n: R, d: R, round: Rounding) -> (bool, R) {
    let (an, ad) = (n.abs(), d.abs());
    let (q, rest) = udivrem([an.lo, an.hi, 0, 0], ad, 64);
    let negative = n.is_neg() != d.is_neg();
    let up = match round {
        Rounding::TowardZero => false,
        Rounding::Floor => negative && !rest.is_zero(),
        Rounding::Nearest => rest.cmp(ad.sub(rest)) != Ordering::Less,
    };
    let mag = R::new(q[1], q[0]);
    (negative, if up { mag.add(R::new(0, 1)) } else { mag })
}

fn wrap(negative: bool, mag: R) -> i32 {
    if negative {
        mag.lo.wrapping_neg() as i32
    } else {
        mag.lo as i32
    }
}

fn saturate(negative: bool, mag: R) -> i32 {
    if negative {
        if mag.hi != 0 || mag.lo > 0x8000_0000 {
            i32::MIN
        } else {
            mag.lo.wrapping_neg() as i32
        }
    } else if mag.hi != 0 || mag.lo > 0x7fff_ffff {
        i32::MAX
    } else {
        mag.lo as i32
    }
}

/// xorshift32, the same stream on every run.
struct Rng(u32);

impl Rng {
    fn next(&mut self) -> u32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.0 = x;
        x
    }
    /// A word of random magnitude, so small, Q12-sized and full-range values all occur.
    fn word(&mut self) -> u32 {
        let v = self.next();
        let w = self.next();
        w >> (v % 32)
    }
    /// A 64-bit value of random magnitude and sign.
    fn wide(&mut self) -> R {
        let v = self.next();
        let (hi, lo) = (self.next(), self.next());
        let r = match v & 3 {
            0 => R::new(hi, lo),
            1 => R::of(self.word() as i32),
            2 => R::new(hi >> (self.next() % 32), lo),
            _ => R::new(0, lo >> (self.next() % 32)),
        };
        if v & 4 != 0 {
            r.neg()
        } else {
            r
        }
    }
}

struct Run {
    cases: u32,
    failures: u32,
}

impl Run {
    fn check(&mut self, name: &str, ok: bool) {
        self.cases += 1;
        if !ok {
            self.failures += 1;
            if self.failures <= 16 {
                tty::print("  FAIL ");
                tty::println(name);
            }
        }
    }
}

fn to_wide(r: R) -> Wide {
    Wide::from_parts(black_box(r.hi) as i32, black_box(r.lo))
}

fn to_wide_u(r: R) -> WideU {
    WideU::from_parts(black_box(r.hi), black_box(r.lo))
}

const EDGE_WORDS: [u32; 12] = [
    0,
    1,
    2,
    3,
    0xffff,
    0x1_0000,
    0x7fff_ffff,
    0x8000_0000,
    0x8000_0001,
    0xffff_ffff,
    0xffff_fffe,
    0x1234_5678,
];

const ROUNDS: [Rounding; 3] = [Rounding::TowardZero, Rounding::Floor, Rounding::Nearest];

/// Every 64-bit value the checks run through: the edge words as both halves, then random.
fn values(rng: &mut Rng, out: &mut [R; 200]) {
    let mut n = 0;
    for &hi in &EDGE_WORDS {
        for &lo in &EDGE_WORDS[..8] {
            out[n] = R::new(hi, lo);
            n += 1;
        }
    }
    while n < out.len() {
        out[n] = rng.wide();
        n += 1;
    }
}

fn unsigned_ops(run: &mut Run, vals: &[R; 200]) {
    for (i, &a) in vals.iter().enumerate() {
        let wa = to_wide_u(a);
        for j in 0..12 {
            let b = vals[(i * 5 + j * 17 + 3) % vals.len()];
            // 128-bit product.
            let (high, low) = wa.mul_full(to_wide_u(b));
            let want = mul_full(a, b);
            run.check(
                "mul_full",
                [low.low(), low.high(), high.low(), high.high()] == want,
            );
            if b.is_zero() {
                continue;
            }
            // Division by a word and by a wide value.
            let (qw, rest) = udivrem([a.lo, a.hi, 0, 0], b, 64);
            let wb = to_wide_u(b);
            run.check(
                "quotient",
                wa.quotient(wb) == if qw[1] != 0 { u32::MAX } else { qw[0] },
            );
            if b.hi == 0 {
                let (q, r) = wa.div_rem_u32(black_box(b.lo));
                run.check(
                    "div_rem_u32",
                    q.low() == qw[0] && q.high() == qw[1] && R::new(0, r) == rest,
                );
            }
            // Ratio order: a/b against the next two values.
            let c = vals[(i * 3 + j * 11 + 1) % vals.len()];
            let d = vals[(i * 7 + j * 13 + 5) % vals.len()];
            if !d.is_zero() {
                let want = cmp_words(mul_full(a, d), mul_full(c, b));
                run.check(
                    "cmp_ratio",
                    WideU::cmp_ratio(wa, wb, to_wide_u(c), to_wide_u(d)) == want,
                );
            }
        }
    }
}

fn scale_ops(run: &mut Run, rng: &mut Rng, vals: &[R; 200]) {
    for i in 0..1500usize {
        let den = vals[i % vals.len()];
        if den.is_zero() {
            continue;
        }
        // A fraction t <= den: den itself, zero, or den scaled down by a random shift.
        let t = match rng.next() % 4 {
            0 => den,
            1 => R::new(0, 0),
            _ => {
                let shifted = shr(den, rng.next() % 64);
                shifted
            }
        };
        let a = rng.word();
        let product = mul_full(R::new(0, a), t);
        let (q, _) = udivrem(product, den, 96);
        run.check(
            "scale_by_ratio",
            to_wide_u(t).scale_by_ratio(black_box(a), to_wide_u(den)) == q[0],
        );
    }
}

fn shr(r: R, n: u32) -> R {
    if n == 0 {
        r
    } else if n < 32 {
        R::new(r.hi >> n, (r.lo >> n) | (r.hi << (32 - n)))
    } else {
        R::new(0, r.hi >> (n - 32))
    }
}

fn signed_ops(run: &mut Run, rng: &mut Rng, vals: &[R; 200]) {
    for (i, &n) in vals.iter().enumerate() {
        let wn = to_wide(n);
        // Word divisors: the edge words as signed values, and random ones.
        for j in 0..14usize {
            let d32 = if j < EDGE_WORDS.len() {
                EDGE_WORDS[j]
            } else {
                rng.word()
            };
            if d32 == 0 {
                continue;
            }
            let d32 = d32 as i32;
            for round in ROUNDS {
                let (neg, mag) = signed_quotient(n, R::of(d32), round);
                run.check(
                    "div_i32_wrap",
                    wn.div_i32_wrap(black_box(d32), round) == wrap(neg, mag),
                );
                run.check(
                    "div_i32_sat",
                    wn.div_i32_sat(black_box(d32), round) == saturate(neg, mag),
                );
            }
        }
        // Wide divisors.
        for j in 0..8usize {
            let d = vals[(i * 5 + j * 23 + 1) % vals.len()];
            if d.is_zero() {
                continue;
            }
            for round in ROUNDS {
                let (neg, mag) = signed_quotient(n, d, round);
                run.check(
                    "div_wide_sat",
                    wn.div_wide_sat(to_wide(d), round) == saturate(neg, mag),
                );
            }
        }
        // Division by a power of two truncates toward zero.
        for s in [0u32, 1, 12, 31, 32, 33, 62] {
            let s = black_box(s);
            let (neg, mag) = signed_quotient(n, R::new(0, 1).shl(s), Rounding::TowardZero);
            let want = if neg { mag.neg() } else { mag };
            let got = wn.div_pow2(s);
            run.check(
                "div_pow2",
                got.high() as u32 == want.hi && got.low_u32() == want.lo,
            );
        }
    }
}

impl R {
    fn shl(self, n: u32) -> R {
        if n == 0 {
            self
        } else if n < 32 {
            R::new((self.hi << n) | (self.lo >> (32 - n)), self.lo << n)
        } else {
            R::new(self.lo << (n - 32), 0)
        }
    }
}

// ---------------------------------------------------------------------------------------
// Timing.

/// Calls per batch. 64 calls of at most a few thousand cycles stay well inside the 16-bit
/// counter (524,288 cycles).
const BATCH: u32 = 64;
/// Batches averaged per figure.
const REPS: u32 = 8;

const T2_COUNTER: *const u32 = (psx_hw::timers::block(2) + psx_hw::timers::COUNTER) as *const u32;
const T2_MODE: *mut u32 = (psx_hw::timers::block(2) + psx_hw::timers::MODE) as *mut u32;
const T2_SYSCLK_DIV8: u32 = 1 << 9;

fn now() -> u32 {
    // SAFETY: a read of root counter 2's current-value register.
    unsafe { read_volatile(T2_COUNTER) & 0xffff }
}

/// Counter ticks (8 CPU cycles each) for `REPS` batches of `BATCH` calls of `body(i)`.
fn ticks(mut body: impl FnMut(usize)) -> u32 {
    let mut total = 0u32;
    for _ in 0..REPS {
        let start = now();
        for i in 0..BATCH as usize {
            body(i);
        }
        total += now().wrapping_sub(start) & 0xffff;
    }
    total
}

fn print_dec(mut v: u32) {
    let mut buf = [0u8; 10];
    let mut n = 0;
    if v == 0 {
        buf[0] = b'0';
        n = 1;
    }
    while v > 0 {
        buf[n] = b'0' + (v % 10) as u8;
        v /= 10;
        n += 1;
    }
    let mut out = [0u8; 10];
    for i in 0..n {
        out[i] = buf[n - 1 - i];
    }
    // SAFETY: only ASCII digits were written.
    tty::print(unsafe { core::str::from_utf8_unchecked(&out[..n]) });
}

fn report(label: &str, total_ticks: u32, base_ticks: u32) {
    let cycles = total_ticks.saturating_sub(base_ticks) * 8 / (REPS * BATCH);
    tty::print("widediv: ");
    tty::print(label);
    tty::print(" cycles_per_call=");
    print_dec(cycles);
    tty::print("\n");
}

/// Operand sets for the figures. Each set has 16 entries, indexed round-robin.
struct Sets {
    /// Numerators that fit 32 bits.
    small: [(u32, u32); 16],
    /// Numerators of every magnitude up to 64 bits (high word nonzero).
    big: [(u32, u32); 16],
    /// Divisors of every magnitude that fit 32 bits.
    word: [u32; 16],
    /// Divisors from 2^32 up.
    wide: [(u32, u32); 16],
}

fn sets(rng: &mut Rng) -> Sets {
    let mut s = Sets {
        small: [(0, 0); 16],
        big: [(0, 0); 16],
        word: [1; 16],
        wide: [(1, 1); 16],
    };
    for i in 0..16 {
        s.small[i] = (0, rng.word() | 1);
        s.big[i] = (rng.word() | 1, rng.next());
        s.word[i] = rng.word() | 1;
        s.wide[i] = (rng.word() | 1, rng.next());
    }
    s
}

fn bench(rng: &mut Rng) {
    // SAFETY: counter 2's mode register; nothing else uses the counter here.
    unsafe { write_volatile(T2_MODE, T2_SYSCLK_DIV8) };
    let s = sets(rng);
    let mut sink = 0u32;
    let base = ticks(|i| {
        let a = black_box(s.big[i & 15]);
        let d = black_box(s.word[i & 15]);
        sink = sink.wrapping_add(a.0 ^ a.1 ^ d);
    });
    let wu = |p: (u32, u32)| WideU::from_parts(black_box(p.0), black_box(p.1));
    let ws = |p: (u32, u32)| Wide::from_parts(black_box(p.0) as i32, black_box(p.1));
    let mut bench_u = |label: &str, f: &mut dyn FnMut(usize) -> u32| {
        let t = ticks(|i| sink = sink.wrapping_add(f(i)));
        report(label, t, base);
    };
    bench_u("div_rem_u32 (numerator < 2^32)", &mut |i| {
        wu(s.small[i & 15]).div_rem_u32(black_box(s.word[i & 15])).1
    });
    bench_u("div_rem_u32 (64-bit numerator)", &mut |i| {
        wu(s.big[i & 15]).div_rem_u32(black_box(s.word[i & 15])).1
    });
    bench_u("quotient (word divisor)", &mut |i| {
        wu(s.big[i & 15]).quotient(WideU::of(black_box(s.word[i & 15])))
    });
    bench_u("quotient (wide divisor)", &mut |i| {
        wu(s.big[i & 15]).quotient(wu(s.wide[i & 15]))
    });
    bench_u("mul_full", &mut |i| {
        wu(s.big[i & 15]).mul_full(wu(s.wide[i & 15])).1.low()
    });
    bench_u("cmp_ratio", &mut |i| {
        WideU::cmp_ratio(
            wu(s.big[i & 15]),
            wu(s.wide[i & 15]),
            wu(s.wide[(i + 1) & 15]),
            wu(s.big[(i + 5) & 15]),
        ) as u32
    });
    bench_u("scale_by_ratio (wide denominator)", &mut |i| {
        // t <= den: the numerator word pair shifted down against the full denominator.
        let den = wu(s.wide[i & 15]);
        let t = den.shr_by(black_box(1));
        t.scale_by_ratio(black_box(s.word[i & 15]), den)
    });
    bench_u("div_i32_wrap TowardZero (numerator < 2^32)", &mut |i| {
        ws(s.small[i & 15]).div_i32_wrap(black_box(s.word[i & 15]) as i32, Rounding::TowardZero)
            as u32
    });
    bench_u("div_i32_wrap TowardZero (64-bit numerator)", &mut |i| {
        ws(s.big[i & 15]).div_i32_wrap(black_box(s.word[i & 15]) as i32, Rounding::TowardZero)
            as u32
    });
    bench_u("div_i32_sat Nearest (64-bit numerator)", &mut |i| {
        ws(s.big[i & 15]).div_i32_sat(black_box(s.word[i & 15]) as i32, Rounding::Nearest) as u32
    });
    bench_u("div_i32_sat Floor (numerator < 2^32)", &mut |i| {
        ws(s.small[i & 15]).div_i32_sat(black_box(s.word[i & 15]) as i32, Rounding::Floor) as u32
    });
    bench_u("div_wide_sat Nearest (wide divisor)", &mut |i| {
        ws(s.big[i & 15]).div_wide_sat(ws(s.wide[i & 15]), Rounding::Nearest) as u32
    });
    bench_u("div_pow2", &mut |i| {
        ws(s.big[i & 15]).div_pow2(black_box(12)).low() as u32
    });
    black_box(sink);
}

#[no_mangle]
fn main() {
    let mut run = Run {
        cases: 0,
        failures: 0,
    };
    let mut rng = Rng(0x9e37_79b9);
    let mut vals = [R::new(0, 0); 200];
    values(&mut rng, &mut vals);
    unsigned_ops(&mut run, &vals);
    scale_ops(&mut run, &mut rng, &vals);
    signed_ops(&mut run, &mut rng, &vals);
    if run.failures == 0 {
        tty::print("WIDEDIV PASS cases=");
        tty::print_hex_u32(run.cases);
    } else {
        tty::print("WIDEDIV FAIL failures=");
        tty::print_hex_u32(run.failures);
        tty::print(" of=");
        tty::print_hex_u32(run.cases);
    }
    tty::println("");
    bench(&mut rng);
    tty::println("WIDEDIV DONE");
    loop {}
}

[package]
name    = "hello-xa"
version = "0.1.0"
edition = "2021"
