[workspace]

[[bin]]
name = "hello-xa"
path = "src/main.rs"

# Plays a file interleaved for double speed (`xa-encode --speed 2`).
[features]
double-speed = []

[profile.release]
panic = "abort"
codegen-units = 1
lto = true

[dependencies]
psx-font = { path = "../../crates/psx-font" }
psx-fmv  = { path = "../../crates/psx-fmv" }
psx-gpu  = { path = "../../crates/psx-gpu" }
psx-io   = { path = "../../crates/psx-io" }
