//! `hello-xa-resume` -- a song survives a data read.
//!
//! Plays one channel of `SONGS.XA`, suspends it, reads sixteen data sectors
//! through the polled reader (which rewrites the drive mode and leaves the head
//! at the data), resumes, and checks what the player and the song clock saw:
//!
//! 1. the song streams, and the song clock stays with the head readings;
//! 2. the data read returns every sector it asked for;
//! 3. `resume` is accepted;
//! 4. the head is back inside the song file (not at the data) within five
//!    seconds, near where the pause left it, and keeps pace afterwards.
//!
//! The channel and the mode are checked outside, from the drive command log and
//! the audio capture (`tools/xa_resume_gate.sh`). The verdict goes to the TTY
//! at the end (`hello-xa-resume: ALL PASS`) and to the screen.

#![no_std]
#![no_main]

extern crate psx_rt;

use psx_fmv::iso;
use psx_font::fonts::BASIC;
use psx_font::FontAtlas;
use psx_gpu::display::{DisplayConfig, DoubleBuffer, Resolution, VideoMode};
use psx_gpu::Gpu;
use psx_io::cd::xa::{DriveSpeed, File, Player};
use psx_io::cd::xa_clock::SongClock;
use psx_io::periph::Cd;
use psx_pack::cd::{SectorReader, SECTOR_WORDS};
use psx_rt::interrupts::{vblank_count, wait_vblank};
use psx_spu::{self as spu, CdVolume, Spu, Volume};
use psx_vram::{Clut, TextureDepth, TexturePage};

const FONT_TPAGE: TexturePage = TexturePage::new(320, 0, TextureDepth::Bit4);
const FONT_CLUT: Clut = Clut::new(320, 256);

const SONGS_FILE: &str = "SONGS.XA";
const FILE_NUMBER: u8 = 1;
/// The whistle: a continuous 950 to 1900 Hz sweep, easy to tell from the
/// default filter (file 1, channel 1) a drive starts with.
const CHANNEL: u8 = 3;
const VBLANK_HZ: u32 = 60;
/// Frames the song plays before the data read, and after the resume.
const PLAY_FRAMES: u32 = 4 * VBLANK_HZ;
/// Frames to wait for the head to reach the song, at the start and after the
/// resume.
const PATIENCE_FRAMES: u32 = 5 * VBLANK_HZ;
/// Data sectors read while the song is suspended, from the ISO volume
/// descriptors on.
const DATA_SECTORS: u32 = 16;
const DATA_LBA: u32 = iso::PVD_LBA;

/// After the resume the player is polled this often, as a game that only
/// needs the clock would (the clock interpolates in between).
const SPARSE_POLL_FRAMES: u32 = 20;
/// How far the clock may sit from a fresh head reading: half a sector, a
/// frame, and the emulator's frame period against the nominal 60 Hz.
const CLOCK_SLACK_MS: u32 = 40;

const MAX_LINES: usize = 12;

struct Report {
    text: [u8; 1024],
    len: usize,
    ok: bool,
    lines: [(u16, u16, bool); MAX_LINES],
    line_count: usize,
}

static mut REPORT: Report = Report {
    text: [0; 1024],
    len: 0,
    ok: true,
    lines: [(0, 0, false); MAX_LINES],
    line_count: 0,
};

impl Report {
    fn push(&mut self, s: &str) {
        for &b in s.as_bytes() {
            if self.len < self.text.len() {
                self.text[self.len] = b;
                self.len += 1;
            }
        }
    }

    fn num(&mut self, mut value: u32) {
        let mut digits = [0u8; 10];
        let mut at = digits.len();
        loop {
            at -= 1;
            digits[at] = b'0' + (value % 10) as u8;
            value /= 10;
            if value == 0 {
                break;
            }
        }
        for &b in &digits[at..] {
            if self.len < self.text.len() {
                self.text[self.len] = b;
                self.len += 1;
            }
        }
    }

    /// One check: `name`, its verdict and the numbers behind it.
    fn check(&mut self, name: &str, ok: bool, values: &[(&str, u32)]) {
        let from = self.len;
        self.push("hello-xa-resume: ");
        self.push(name);
        self.push(if ok { ": ok" } else { ": FAIL" });
        for &(label, value) in values {
            self.push(" ");
            self.push(label);
            self.push("=");
            self.num(value);
        }
        self.push("\n");
        if self.line_count < MAX_LINES {
            self.lines[self.line_count] = (from as u16, self.len as u16, ok);
            self.line_count += 1;
        }
        self.ok &= ok;
    }

    fn text(&self) -> &str {
        core::str::from_utf8(&self.text[..self.len]).unwrap_or("?")
    }
}

fn read_one<'s>(
    reader: &mut SectorReader,
    sector: &'s mut [u32; SECTOR_WORDS],
    lba: u32,
) -> Option<&'s [u8]> {
    if !reader.start_read(lba) {
        return None;
    }
    let ok = reader.read_sector(sector);
    reader.stop();
    // SAFETY: a `[u32; N]` viewed as its own bytes; alignment only shrinks.
    ok.then(|| unsafe {
        core::slice::from_raw_parts(sector.as_ptr().cast::<u8>(), SECTOR_WORDS * 4)
    })
}

fn find_songs(cd: Cd) -> (Option<File>, Cd) {
    let mut reader = SectorReader::with_cd(cd);
    let mut sector = [0u32; SECTOR_WORDS];
    let file = lookup(&mut reader, &mut sector);
    (file, reader.release())
}

fn lookup(reader: &mut SectorReader, sector: &mut [u32; SECTOR_WORDS]) -> Option<File> {
    if !reader.prepare() {
        return None;
    }
    let (root, _) = iso::root_directory(read_one(reader, sector, iso::PVD_LBA)?)?;
    let (lba, size) = iso::find_in_directory(read_one(reader, sector, root)?, SONGS_FILE)?;
    Some(File::from_directory_entry(
        lba,
        size,
        FILE_NUMBER,
        DriveSpeed::Single,
    ))
}

/// What one run of the song looked like to the player and the clock.
#[derive(Copy, Clone)]
struct Run {
    /// Frames until the head was inside the file, or `None` if it never was.
    frames_to_stream: Option<u32>,
    /// `Player::elapsed_millis` at the first streaming frame.
    first_elapsed: u32,
    /// Clock reading at the first streaming frame, and at the end.
    clock_first: u32,
    clock_last: u32,
    /// Frames from the first streaming frame to the end.
    streamed_frames: u32,
    /// `Player::elapsed_millis` at the end.
    last_elapsed: u32,
    /// The clock never read lower than before.
    monotonic: bool,
    /// Largest distance between the clock and a fresh head reading (the
    /// middle of its sector), in milliseconds, at the frames that took one.
    worst_clock_error: u32,
}

/// Update the clock every frame, and poll the player every `poll_every`
/// frames, until the head has been inside the file for `play_frames` frames or
/// `PATIENCE_FRAMES` pass without it.
fn run_song(player: &mut Player, clock: &mut SongClock, play_frames: u32, poll_every: u32) -> Run {
    let mut run = Run {
        frames_to_stream: None,
        first_elapsed: 0,
        clock_first: 0,
        clock_last: 0,
        streamed_frames: 0,
        last_elapsed: 0,
        monotonic: true,
        worst_clock_error: 0,
    };
    let mut last_serial = None;
    let begin = vblank_count();
    let mut streaming_since = 0;
    loop {
        wait_vblank();
        let now = vblank_count();
        if now.wrapping_sub(begin) % poll_every == 0 {
            player.poll();
        }
        let reading = clock.update(player, now);
        if let Some(ms) = reading {
            if run.frames_to_stream.is_none() {
                run.frames_to_stream = Some(now.wrapping_sub(begin));
                run.first_elapsed = player.elapsed_millis();
                run.clock_first = ms;
                streaming_since = now;
            } else if ms < run.clock_last {
                run.monotonic = false;
            }
            if let Some(sample) = player.head_sample() {
                if last_serial != Some(sample.serial) {
                    last_serial = Some(sample.serial);
                    run.worst_clock_error = run
                        .worst_clock_error
                        .max(ms.abs_diff(sample.centre_millis()));
                }
            }
            run.clock_last = ms;
            run.streamed_frames = now.wrapping_sub(streaming_since);
            run.last_elapsed = player.elapsed_millis();
            if run.streamed_frames >= play_frames {
                return run;
            }
        } else if run.frames_to_stream.is_none() && now.wrapping_sub(begin) > PATIENCE_FRAMES {
            return run;
        }
    }
}

fn within(value: u32, expected: u32, slack: u32) -> bool {
    value.abs_diff(expected) <= slack
}

#[no_mangle]
fn main() {
    let Some(peripherals) = psx_rt::Peripherals::take() else {
        return;
    };
    let mut gpu = Gpu::new(
        peripherals.gpu_dma,
        DisplayConfig::new(VideoMode::Ntsc, Resolution::R320X240),
    );
    let mut fb = DoubleBuffer::new(Resolution::R320X240);
    gpu.set_draw_area((0, 0), (319, 239));
    gpu.set_draw_offset((0, 0));
    let font = FontAtlas::upload(&BASIC, FONT_TPAGE, FONT_CLUT);

    let _spu = Spu::new(peripherals.spu_dma);
    spu::set_main_volume(Volume::MAX, Volume::MAX);
    spu::set_cd_volume(CdVolume::MAX, CdVolume::MAX);
    spu::enable_cd_audio(true);

    // SAFETY: the only reference to the report; the program is single-threaded
    // and interrupts never touch it.
    let report = unsafe { &mut *core::ptr::addr_of_mut!(REPORT) };
    let (file, cd) = find_songs(peripherals.cd);
    let mut player = Player::new(cd);
    let mut clock = SongClock::new(VBLANK_HZ);

    if let Some(file) = file {
        let started = player.play(file.song(CHANNEL), false).is_ok();
        let before = run_song(&mut player, &mut clock, PLAY_FRAMES, 1);
        let streamed = started && before.frames_to_stream.is_some();
        report.check(
            "song streams",
            streamed,
            &[
                ("frames", before.frames_to_stream.unwrap_or(0)),
                ("at_ms", before.first_elapsed),
            ],
        );
        // The clock sits on the head readings (half a sector and a frame of
        // slack), and never moved backwards.
        report.check(
            "clock follows the head",
            streamed && before.monotonic && before.worst_clock_error <= CLOCK_SLACK_MS,
            &[("worst_ms", before.worst_clock_error)],
        );

        // The pause position, as the player last saw it.
        let paused_at = player.elapsed_millis();
        let read = player.with_cd_suspended(|cd| {
            let mut reader = SectorReader::with_cd(cd);
            let mut sector = [0u32; SECTOR_WORDS];
            let mut got = 0;
            if reader.prepare() && reader.start_read(DATA_LBA) {
                while got < DATA_SECTORS && reader.read_sector(&mut sector) {
                    got += 1;
                }
                reader.stop();
            }
            (reader.release(), got)
        });
        let sectors = read.unwrap_or(0);
        report.check(
            "data read while suspended",
            read.is_ok() && sectors == DATA_SECTORS,
            &[("sectors", sectors)],
        );

        let resumed = player.resume();
        report.check("resume accepted", resumed.is_ok(), &[]);

        let after = run_song(&mut player, &mut clock, PLAY_FRAMES, SPARSE_POLL_FRAMES);
        let back = resumed.is_ok() && after.frames_to_stream.is_some();
        report.check(
            "head back in the song",
            back,
            &[
                ("frames", after.frames_to_stream.unwrap_or(0)),
                ("paused_ms", paused_at),
                ("resumed_ms", after.first_elapsed),
            ],
        );
        // Near the pause: not at the top of the file, not far ahead. The
        // window covers the seek back from the data and a sector or two.
        report.check(
            "position kept",
            back && after.first_elapsed + 100 >= paused_at
                && after.first_elapsed <= paused_at + 700,
            &[
                ("paused_ms", paused_at),
                ("resumed_ms", after.first_elapsed),
            ],
        );
        let expected_ms = after.streamed_frames * 1000 / VBLANK_HZ;
        let advanced = after.last_elapsed.saturating_sub(after.first_elapsed);
        report.check(
            "keeps playing",
            back && after.monotonic && within(advanced, expected_ms, 100 + SPARSE_POLL_FRAMES * 17),
            &[("advanced_ms", advanced), ("frames_ms", expected_ms)],
        );
        // Polling every 20 frames, as a game would, the clock is smooth in
        // between and starts again from the resumed position.
        report.check(
            "clock restarts at the resumed position",
            back && after.monotonic
                && within(after.clock_first, after.first_elapsed, 60)
                && after.worst_clock_error <= CLOCK_SLACK_MS,
            &[
                ("clock_first_ms", after.clock_first),
                ("elapsed_first_ms", after.first_elapsed),
                ("worst_ms", after.worst_clock_error),
            ],
        );
        player.stop();
    } else {
        report.check("song file found", false, &[]);
    }

    psx_rt::tty::print(report.text());
    psx_rt::tty::println(if report.ok {
        "hello-xa-resume: ALL PASS"
    } else {
        "hello-xa-resume: FAIL"
    });

    loop {
        let bg = if report.ok {
            (16, 96, 32)
        } else {
            (110, 20, 20)
        };
        fb.clear(&mut gpu, bg);
        font.draw_text(8, 6, "HELLO-XA-RESUME", (230, 230, 240));
        let mut y: i16 = 22;
        for i in 0..report.line_count {
            let (from, to, ok) = report.lines[i];
            let text =
                core::str::from_utf8(&report.text[from as usize..to as usize]).unwrap_or("?");
            let name = text
                .strip_prefix("hello-xa-resume: ")
                .and_then(|t| t.split(':').next())
                .unwrap_or("?");
            let tint = if ok { (80, 220, 100) } else { (230, 80, 80) };
            font.draw_text(8, y, if ok { "OK" } else { "XX" }, tint);
            font.draw_text(32, y, name, tint);
            y += 12;
        }
        gpu.wait_idle();
        wait_vblank();
        fb.swap(&mut gpu);
    }
}

//! `pad-engine-check` -- the interrupt-driven pad engine, measured against the
//! synchronous driver on the same frames.
//!
//! Phases of 120 frames each, in one program. The main loop does one
//! unit of "game work" (a counter increment) until the next VBlank, so the
//! iterations per frame are the CPU the game keeps:
//!
//! 1. nothing polls: the ceiling;
//! 2. the synchronous driver polls both ports once per frame, as a two-player
//!    game does;
//! 3. the engine polls, in each of its configurations, and the loop reads its
//!    snapshot.
//!
//! Then it exercises the lease (a memory card's turn) and reports the engine's
//! counters. Every result is a `padcheck:` line on the TTY, for a headless run
//! (`frontend launch --path pad-engine-check.exe --steps ...`); a press on pad
//! 1 (`--pad-pulses`) shows up as a `buttons=` line in phase 3.
#![no_std]
#![no_main]
#![allow(deprecated)]

extern crate psx_rt;

use psx_io::cd::reader::{SectorReader, SECTOR_WORDS};
use psx_pad::engine::{BytePacing, Config};
use psx_pad::{console, poll_on, Port};
use psx_rt::interrupts::{install_vblank_counter, vblank_count};
use psx_rt::tty;

const FRAMES: u32 = 120;

fn dec(mut v: u32) {
    let mut digits = [0u8; 10];
    let mut n = 0;
    loop {
        digits[n] = b'0' + (v % 10) as u8;
        n += 1;
        v /= 10;
        if v == 0 {
            break;
        }
    }
    while n > 0 {
        n -= 1;
        psx_rt::bios::write_char(digits[n]);
    }
}

fn line(label: &str, value: u32) {
    tty::print("padcheck: ");
    tty::print(label);
    tty::print("=");
    dec(value);
    tty::print("\n");
}

/// Spin until the next VBlank; returns the iterations spent.
fn spin_to_next_vblank() -> u32 {
    let start = vblank_count();
    let mut iterations = 0u32;
    while vblank_count() == start {
        iterations = iterations.wrapping_add(1);
    }
    iterations
}

#[no_mangle]
fn main() {
    let peripherals = psx_rt::Peripherals::take().expect("peripherals are taken once");
    let mut port = peripherals.controller_port;
    install_vblank_counter();

    // Phase 1: nothing polls.
    spin_to_next_vblank();
    let mut total = 0u32;
    for _ in 0..FRAMES {
        total = total.wrapping_add(spin_to_next_vblank() / 16);
    }
    let idle = total / FRAMES;
    line("idle_work_per_frame_x16", idle);

    // Phase 2: the synchronous driver, both ports.
    let mut total = 0u32;
    for _ in 0..FRAMES {
        let _ = poll_on(&mut port, Port::One);
        let _ = poll_on(&mut port, Port::Two);
        total = total.wrapping_add(spin_to_next_vblank() / 16);
    }
    let sync = total / FRAMES;
    line("sync_work_per_frame_x16", sync);

    // Phase 3: the engine, in each configuration, 120 frames apiece.
    if console::install(port, Config::DEFAULT).is_err() {
        tty::println("padcheck: install refused");
        loop {}
    }
    line("installed", u32::from(console::is_installed()));
    let nothing = Config {
        ports: [false, false],
        ..Config::DEFAULT
    };
    let timed = Config {
        pacing: BytePacing::Timed,
        ..Config::DEFAULT
    };
    let every_other = Config {
        kick_every: 2,
        ..Config::DEFAULT
    };
    let variants: [(&str, Config); 6] = [
        ("engine_no_ports", nothing),
        ("engine_port1", Config::PORT1_ONLY),
        ("engine_both", Config::DEFAULT),
        ("engine_both_timed", timed),
        ("engine_both_every_other", every_other),
        ("engine_both", Config::DEFAULT),
    ];
    let mut last_buttons = 0xffff_u16;
    let mut last_seq = 0u32;
    let mut frame_no = 0u32;
    let mut work = [0u32; 6];
    for (slot, (label, config)) in variants.into_iter().enumerate() {
        console::configure(config);
        let before = console::stats();
        let mut total = 0u32;
        for _ in 0..FRAMES {
            total = total.wrapping_add(spin_to_next_vblank() / 16);
            frame_no += 1;
            let snap = console::snapshot();
            let one = snap.port(Port::One);
            if one.pad.buttons.bits() != last_buttons && snap.seq != 0 {
                last_buttons = one.pad.buttons.bits();
                tty::print("padcheck: frame=");
                dec(frame_no);
                tty::print(" buttons=0x");
                tty::print_hex_u32(u32::from(last_buttons));
                tty::print(" mode=");
                dec(one.pad.mode as u32);
                tty::print("\n");
            }
            last_seq = snap.seq;
        }
        work[slot] = total / FRAMES;
        line(label, work[slot]);
        let after = console::stats();
        line(
            "  events_per_frame_x10",
            (after.events - before.events) * 10 / FRAMES,
        );
    }
    line("seq", last_seq);
    let snap = console::snapshot();
    line("port1_health", snap.port(Port::One).health as u32);
    line("port1_updates", snap.port(Port::One).updates);
    line("port1_faults", snap.port(Port::One).faults);
    line("port1_mode", snap.port(Port::One).pad.mode as u32);
    line("port2_health", snap.port(Port::Two).health as u32);
    line("port2_faults", snap.port(Port::Two).faults);

    // The lease: a card's turn. Hold the port across three VBlanks.
    let skips_before = console::stats().leased_skips;
    {
        let _lease = console::lease();
        let start = vblank_count();
        while vblank_count().wrapping_sub(start) < 3 {}
    }
    line("leased_skips", console::stats().leased_skips - skips_before);
    for _ in 0..4 {
        spin_to_next_vblank();
    }
    let updates_after_lease = console::snapshot().port(Port::One).updates;
    line("updates_after_lease", updates_after_lease);

    // A memory card's turn for real: read frames through the lease while the
    // engine runs and the card raises IRQ7 with every ACK. The engine must
    // leave the ACK latch the card driver waits on alone (before it did, the
    // first byte timed out and the card read as absent). Needs a card in port
    // 1, which the headless frontend provides (`--memcard`).
    let mut card_ok = 0u32;
    let mut card_failed = 0u32;
    let updates_before_card = console::snapshot().port(Port::One).updates;
    for frame in 0..8u16 {
        {
            let mut lease = console::lease();
            let mut card = psx_mc::HardwareCard::on_port(&mut *lease, psx_mc::Slot::One);
            let mut out = [0u8; psx_mc::FRAME_SIZE];
            match psx_mc::Block::read_frame(&mut card, frame, &mut out) {
                Ok(()) => card_ok += 1,
                Err(_) => card_failed += 1,
            }
        }
        spin_to_next_vblank();
        spin_to_next_vblank();
    }
    let card_pad_updates = console::snapshot().port(Port::One).updates - updates_before_card;
    line("card_reads_ok", card_ok);
    line("card_reads_failed", card_failed);
    line("card_pad_updates", card_pad_updates);

    // A polled CD read, as the SDK's pack loader and FMV streamer do it, holds
    // I_MASK at VBlank for its whole stream. The engine must keep running
    // through it: before the mask kept its sources, every transaction stalled
    // and faulted, one per VBlank. Needs feature `cd-read` and a disc (`--disc`).
    let mut reader = SectorReader::with_cd(peripherals.cd);
    let mut cd_stalls = 0;
    let mut cd_faults = 0;
    let mut cd_updates = 0;
    let mut cd_ran = false;
    if cfg!(feature = "cd-read") && reader.prepare() && reader.start_read(16) {
        cd_ran = true;
        let before = console::stats();
        let faults_before = console::snapshot().port(Port::One).faults;
        let updates_before = console::snapshot().port(Port::One).updates;
        let mut sector = [0u32; SECTOR_WORDS];
        for _ in 0..60 {
            let _ = reader.read_sector(&mut sector);
            spin_to_next_vblank();
        }
        cd_stalls = console::stats().stalls - before.stalls;
        cd_faults = console::snapshot().port(Port::One).faults - faults_before;
        cd_updates = console::snapshot().port(Port::One).updates - updates_before;
        reader.stop();
        line("cd_load_stalls", cd_stalls);
        line("cd_load_faults", cd_faults);
        line("cd_load_updates", cd_updates);
    } else {
        tty::println("padcheck: polled CD read skipped (feature cd-read and a disc)");
    }
    let cd = reader.release();

    // Hand the port back and take it again, as a program does that gives it
    // to a synchronous driver for a while. The wrapper stays in the vector
    // between; install must find it already in the chain, not refuse.
    let mut reinstalled = 0;
    let mut handed_back = false;
    for _ in 0..6 {
        if let Some(port) = console::uninstall() {
            handed_back = !console::is_installed();
            if console::install(port, Config::DEFAULT).is_ok() {
                let before = console::snapshot().port(Port::One).updates;
                for _ in 0..20 {
                    spin_to_next_vblank();
                }
                reinstalled = console::snapshot().port(Port::One).updates - before;
            }
            break;
        }
        spin_to_next_vblank();
    }
    line("updates_after_reinstall", reinstalled);

    // Motors: the engine maps them (command 0x4D) and sends the request with
    // each poll; stop_motors returns once a poll with them off has gone out.
    console::enable_rumble(Port::One);
    console::set_rumble(Port::One, psx_pad::Rumble::new(true, 200));
    for _ in 0..30 {
        spin_to_next_vblank();
    }
    let rumble_mapped = console::rumble_mapped(Port::One);
    let faults_before_stop = console::snapshot().port(Port::One).faults;
    console::stop_motors();
    let stopped = console::snapshot().port(Port::One).faults == faults_before_stop;
    line("rumble_mapped", u32::from(rumble_mapped));

    // psx-cdstream installs its wrapper after the engine's: the two chain, so
    // the pad keeps being read. (Before they chained, this silenced the pad.)
    let before = console::snapshot().port(Port::One).updates;
    if psx_cdstream::install(cd, psx_cdstream::Config::DEFAULT).is_err() {
        tty::println("padcheck: cdstream install refused");
    }
    for _ in 0..30 {
        spin_to_next_vblank();
    }
    let chained = console::snapshot().port(Port::One).updates - before;
    line("updates_after_cdstream_install", chained);

    // psx-cdstream reading while the engine polls both ports: the stream and
    // the pad share the interrupt chain, and neither may lose the other's
    // interrupts. Needs feature `cd-stream` and a disc.
    #[cfg(feature = "cd-stream")]
    let stream_ok = {
        use psx_cdstream::{Outcome, Request, RequestState};
        static mut SECTORS: [u32; 2048 / 4 * 64] = [0; 2048 / 4 * 64];
        let before = console::stats();
        let faults_before = console::snapshot().port(Port::One).faults;
        // SAFETY: a static buffer of 64 sectors nothing else touches until
        // the request has finished.
        let request = unsafe { Request::new_raw(100, 64, core::ptr::addr_of_mut!(SECTORS).cast()) };
        let mut done = false;
        let mut sectors = 0;
        if let Ok(ticket) = psx_cdstream::submit(request) {
            for _ in 0..240 {
                spin_to_next_vblank();
                psx_cdstream::service();
                if let RequestState::Finished(c) = psx_cdstream::state(ticket) {
                    done = c.outcome == Outcome::Done;
                    sectors = c.received;
                    break;
                }
            }
        }
        line("stream_sectors", sectors);
        line(
            "stream_pad_faults",
            console::snapshot().port(Port::One).faults - faults_before,
        );
        line("stream_pad_stalls", console::stats().stalls - before.stalls);
        done && sectors == 64
    };
    #[cfg(not(feature = "cd-stream"))]
    let stream_ok = true;

    let stats = console::stats();
    line("events", stats.events);
    line("kicks", stats.kicks);
    line("stalls", stats.stalls);
    line("spurious", stats.spurious);
    line("stack_unused", console::handler_stack_unused_bytes() as u32);
    // The gate. Work is iterations of an empty loop per frame, so a larger
    // number is more CPU left to the game.
    let mut failures = 0;
    let mut check = |ok: bool, what: &str| {
        if !ok {
            failures += 1;
            tty::print("padcheck: FAIL ");
            tty::println(what);
        }
    };
    let (no_ports, port1, both, timed) = (work[0], work[1], work[2], work[3]);
    // An empty port 2 and the wrapper's own entry on every VBlank cost almost
    // nothing: within a percent of the idle loop (the loop's phase against the
    // VBlank moves the count by a few tenths of a percent).
    check(
        no_ports * 100 >= idle * 99,
        "VBlank entry alone costs more than 1%",
    );
    // A pad in port 2 (the emulator's `--pad2`) is polled for real, so only
    // an empty socket is expected to be free.
    let populated = snap.port(Port::Two).health == psx_pad::engine::Health::Present;
    // The engine keeps at least 95% of the CPU with both ports polled (90%
    // with a pad in port 2, which the handler waits out `/ACK` pulses of: a
    // pad that holds it for 1,500 cycles costs that much per byte). With an
    // empty port 2 it also keeps more than the synchronous driver, which
    // spends 119,000 cycles a frame finding the port empty (13,000 after the
    // empty-socket fix) on top of the connected pad's 17,000.
    let floor = if populated { 90 } else { 95 };
    check(
        both * 100 >= idle * floor,
        "engine with both ports keeps too little of the CPU",
    );
    if populated {
        tty::println("padcheck: port 2 is populated");
    } else {
        check(
            both > sync,
            "the engine keeps more of the CPU than the synchronous driver",
        );
        check(
            both * 100 >= port1 * 99,
            "an empty port 2 costs more than 1%",
        );
        check(
            snap.port(Port::Two).health == psx_pad::engine::Health::Absent,
            "port 2 is absent",
        );
    }
    check(
        timed * 100 >= idle * floor,
        "fixed pacing keeps too little of the CPU",
    );
    check(
        snap.port(Port::One).health == psx_pad::engine::Health::Present,
        "port 1 is present",
    );
    check(
        snap.port(Port::One).faults == 0 && snap.port(Port::Two).faults == 0,
        "no faults",
    );
    check(
        stats.stalls == 0 && stats.spurious == 0,
        "no stalls or spurious interrupts",
    );
    check(
        console::handler_stack_unused_bytes() >= 256,
        "the handler stack has room",
    );
    check(
        updates_after_lease > snap.port(Port::One).updates,
        "polling resumes after the lease",
    );
    check(
        card_ok == 8 && card_failed == 0,
        "a memory card cannot be read through the lease",
    );
    check(
        card_pad_updates >= 8,
        "the pad is not read between card transactions",
    );
    if cd_ran {
        check(
            cd_stalls == 0 && cd_faults == 0,
            "the engine stalls or faults during a polled CD read",
        );
        check(
            cd_updates >= 45,
            "the pad is still read during a polled CD read",
        );
    }
    check(
        stream_ok,
        "psx-cdstream reads 64 sectors while the engine polls",
    );
    check(
        rumble_mapped,
        "the engine maps the motors of the emulator's pad",
    );
    check(stopped, "stopping the motors does not fault the port");
    check(handed_back, "uninstall hands the port back");
    check(reinstalled >= 15, "install works again after uninstall");
    check(
        chained >= 25,
        "the pad is still read after psx-cdstream installs its wrapper",
    );
    if failures == 0 {
        tty::println("padcheck: PASS");
    }
    tty::println("padcheck: done");
    loop {}
}

//! `pollbench` -- what one controller poll costs, in CPU cycles.
//!
//! Polls port 1, then port 2, then both back to back, `POLLS` times each, and
//! prints the cycles per poll for every phase on the TTY. Root counter 2 runs
//! at the system clock divided by eight and is read around each poll, so the
//! numbers are the guest's own and need no profiler. A game that polls both
//! ports every frame pays the third figure per frame.
//!
//! Run headless with `frontend launch --path pollbench.exe --steps 400000000`
//! and read the `pollbench:` lines. An empty port 2 is the headless default;
//! the cost of an absent socket is the figure this exists to watch.
#![no_std]
#![no_main]
#![allow(deprecated)]

extern crate psx_rt;

use psx_io::timers::{self, Timer};
use psx_rt::tty;

/// Number of polls per phase.
const POLLS: u32 = 200;

/// Mode bit 9 selects system clock / 8 for counter 2.
const T2_SYSCLK_DIV8: u16 = 1 << 9;

fn now() -> u32 {
    u32::from(timers::counter(Timer::Timer2))
}

/// Counter ticks (8 CPU cycles each) spent in `body`, over `POLLS` calls.
fn ticks(mut body: impl FnMut()) -> u32 {
    let mut total = 0u32;
    let mut n = 0;
    while n < POLLS {
        let start = now();
        body();
        total += now().wrapping_sub(start) & 0xffff;
        n += 1;
    }
    total
}

fn report(label: &str, total_ticks: u32) {
    tty::print("pollbench: ");
    tty::print(label);
    tty::print(" cycles_x_polls=0x");
    tty::print_hex_u32(total_ticks.wrapping_mul(8));
    tty::print(" polls=0x");
    tty::print_hex_u32(POLLS);
    tty::print("\n");
}

#[no_mangle]
fn main() {
    timers::set_mode(Timer::Timer2, T2_SYSCLK_DIV8);
    report(
        "port1",
        ticks(|| {
            let _ = psx_pad::poll_port1();
        }),
    );
    report(
        "port2",
        ticks(|| {
            let _ = psx_pad::poll_port2();
        }),
    );
    report(
        "both",
        ticks(|| {
            let _ = psx_pad::poll_port1();
            let _ = psx_pad::poll_port2();
        }),
    );
    tty::println("pollbench: done");
    loop {}
}

//! `sfxbench` -- what the `psx-sfx` bookkeeping costs, in CPU cycles.
//!
//! Times the per-emitter placement chain (`space::gains`), the mixer's per-voice
//! level update, its idle tick and a stealing `play`, each over many calls
//! against a no-op hardware, and prints cycles per call on the TTY. Root counter
//! 2 runs at the system clock divided by eight and is read around each batch, so
//! the numbers are the guest's own and need no profiler. An empty batch with the
//! same input shuffling is measured first and subtracted.
//!
//! Run headless with `frontend launch --path sfxbench.exe --steps 400000000`
//! and read the `sfxbench:` lines. SPU register writes are not part of this:
//! the hardware is [`psx_sfx::hw::NullHw`], so the figures are the bookkeeping
//! alone and the real per-voice cost is these plus the SPU writes.
#![no_std]
#![no_main]

extern crate psx_rt;

use core::hint::black_box;
use core::ptr::{read_volatile, write_volatile};
use psx_rt::tty;
use psx_sfx::hw::NullHw;
use psx_sfx::mixer::{Class, Lane, Mixer, Play, Policy, Sound, SoundId};
use psx_sfx::space::{
    gains, Center, Curve, Emitter, Listener, ListenerRule, Listeners, PanLaw, Space,
};
use psx_sfx::Sample;
use psx_spu::SpuAddr;

/// Calls per batch. 128 calls of at most a few thousand cycles stay well inside
/// the 16-bit counter (524,288 cycles).
const BATCH: u32 = 128;

/// Batches averaged per figure.
const REPS: u32 = 8;

const T2_COUNTER: *const u32 = (psx_hw::timers::block(2) + psx_hw::timers::COUNTER) as *const u32;
const T2_MODE: *mut u32 = (psx_hw::timers::block(2) + psx_hw::timers::MODE) as *mut u32;
const T2_SYSCLK_DIV8: u32 = 1 << 9;

fn now() -> u32 {
    // SAFETY: a read of root counter 2's current-value register.
    unsafe { read_volatile(T2_COUNTER) & 0xffff }
}

/// Counter ticks (8 CPU cycles each) for `REPS` batches of `BATCH` calls of
/// `body(i)`.
fn ticks(mut body: impl FnMut(u32)) -> u32 {
    let mut total = 0u32;
    for _ in 0..REPS {
        let start = now();
        for i in 0..BATCH {
            body(i);
        }
        total += now().wrapping_sub(start) & 0xffff;
    }
    total
}

fn print_dec(mut v: u32) {
    let mut buf = [0u8; 10];
    let mut n = 0;
    if v == 0 {
        buf[0] = b'0';
        n = 1;
    }
    while v > 0 {
        buf[n] = b'0' + (v % 10) as u8;
        v /= 10;
        n += 1;
    }
    let mut out = [0u8; 10];
    for i in 0..n {
        out[i] = buf[n - 1 - i];
    }
    // SAFETY: only ASCII digits were written.
    tty::print(unsafe { core::str::from_utf8_unchecked(&out[..n]) });
}

/// Print cycles per call: (total - baseline) * 8 / (REPS * BATCH).
fn report(label: &str, total_ticks: u32, base_ticks: u32) {
    let cycles = total_ticks.saturating_sub(base_ticks) * 8 / (REPS * BATCH);
    tty::print("sfxbench: ");
    tty::print(label);
    tty::print(" cycles_per_call=");
    print_dec(cycles);
    tty::print("\n");
}

/// Sixteen emitter positions from near to far, so the isqrt and the curve see a
/// spread of magnitudes rather than one constant.
const POS: [[i32; 3]; 16] = [
    [120, 10, 300],
    [-800, 40, 1500],
    [2500, -60, -900],
    [90, 0, 60],
    [-3000, 200, 4000],
    [700, -20, -2200],
    [15, 5, 15],
    [5200, 0, 100],
    [-100, 90, -4800],
    [1800, 300, 1200],
    [-2600, -100, -50],
    [60, 0, 3400],
    [4100, 10, 4100],
    [-700, 0, 700],
    [330, 20, -330],
    [9000, 0, -9000],
];

fn sound(lane: u8, class: Class, looped: bool) -> Sound {
    let s = Sample::resident(SpuAddr::new(0x1010), 22050, 400);
    if looped {
        Sound::looped(SoundId(1), s, lane).with_class(class)
    } else {
        Sound::one_shot(SoundId(1), s, lane).with_class(class)
    }
}

#[no_mangle]
fn main() {
    // SAFETY: counter 2's mode register; nothing else uses the counter here.
    unsafe { write_volatile(T2_MODE, T2_SYSCLK_DIV8) };

    let curve = Curve::linear_clip(0x3fff, 6000);
    let one = Listeners::new([Listener::new([0, 0, 0], 300)]);
    let two = Listeners::new([
        Listener::new([0, 0, 0], 300),
        Listener::new([1200, 0, 900], 3900),
    ]);
    let equal = Space::new(0, PanLaw::EqualPower(Center::Unity));
    let sum = Space::new(0, PanLaw::Sum);
    let off = Space::new(0, PanLaw::Off);
    let culled = Space::new(0, PanLaw::Off).with_cull(0x3000);

    // Baseline: the same index shuffling and a black_box, no work.
    let mut sink = 0i32;
    let base = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        sink = sink.wrapping_add(p[0]);
    });
    black_box(sink);

    let mut acc = 0i32;
    let mut run = |label: &str, space: &Space, rule: ListenerRule, two_ears: bool| {
        let t = ticks(|i| {
            let e = Emitter::new(black_box(POS[(i & 15) as usize]));
            let g = if two_ears {
                gains(space, &two, rule, &e, &curve)
            } else {
                gains(space, &one, rule, &e, &curve)
            };
            if let Some(g) = g {
                acc = acc.wrapping_add(g.left as i32 + g.right as i32);
            }
        });
        report(label, t, base);
    };
    run(
        "gains 1 listener, EqualPower",
        &equal,
        ListenerRule::Loudest,
        false,
    );
    run("gains 1 listener, Sum", &sum, ListenerRule::Loudest, false);
    run(
        "gains 1 listener, Off (no trig, no divide)",
        &off,
        ListenerRule::Loudest,
        false,
    );
    run(
        "gains 2 listeners Loudest, EqualPower",
        &equal,
        ListenerRule::Loudest,
        true,
    );
    run(
        "gains 2 listeners Nearest, EqualPower",
        &equal,
        ListenerRule::Nearest,
        true,
    );
    run(
        "gains 2 listeners Centroid, EqualPower",
        &equal,
        ListenerRule::Centroid,
        true,
    );
    run(
        "gains 1 listener, culled by curve",
        &culled,
        ListenerRule::Loudest,
        false,
    );
    black_box(acc);

    // The pieces the placement chain is built from, for attribution.
    let mut acc2 = 0i32;
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(psx_math::int32::isqrt_i32(
            p[0] * p[0] + p[1] * p[1] + p[2] * p[2],
        ));
    });
    report("  isqrt_i32 of a 3D squared length", t, base);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(psx_math::int32::isqrt_u64(
            (p[0] * p[0] + p[1] * p[1] + p[2] * p[2]) as u64,
        ) as i32);
    });
    report("  isqrt_u64 of the same", t, base);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(psx_math::sin_q12(p[0] as u16) + psx_math::cos_q12(p[0] as u16));
    });
    report("  sin_q12 + cos_q12", t, base);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(black_box(p[0] * 3000) / black_box(p[2] | 1));
    });
    report("  one 32-bit divide plus a multiply", t, base);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(curve.level(black_box(p[0] + p[2])) as i32);
    });
    report("  Curve::level (Ramp)", t, base);
    let hyper = Curve::inverse(0x3fff, 800);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        acc2 = acc2.wrapping_add(hyper.level(black_box(p[0] + p[2])) as i32);
    });
    report("  Curve::level (Hyper)", t, base);
    let t = ticks(|i| {
        let p = black_box(POS[(i & 15) as usize]);
        let q = black_box([5, 6, 7]);
        let d = [
            p[0].wrapping_sub(q[0]) >> 1,
            p[1].wrapping_sub(q[1]) >> 1,
            p[2].wrapping_sub(q[2]) >> 1,
        ];
        let d = d.map(|v| v.clamp(-16383, 16383));
        acc2 = acc2.wrapping_add(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
    });
    report("  three axis offsets, clamps and squares", t, base);
    black_box(acc2);

    // The mixer, over a no-op chip.
    let mut hw = NullHw;
    let mut mixer = Mixer::new(
        [
            Lane::new(0x00_00ff, Policy::Smart),
            Lane::new(0xff_ff00, Policy::FirstFree),
        ],
        60,
    );
    let engine = sound(0, Class::Normal, true);
    let mut handles = [None; 8];
    for (i, h) in handles.iter_mut().enumerate() {
        *h = mixer.play(&mut hw, &engine, Play::new(1000 + i as i16, 1000));
    }

    let t = ticks(|i| {
        let l = black_box(500 + (i & 31) as i16 * 40);
        if let Some(h) = handles[(i & 7) as usize] {
            mixer.update(&mut hw, h, l, 1000 - l / 2);
        }
    });
    report("Mixer::update (levels changed)", t, base);

    let mut clock = 0u32;
    let t = ticks(|_| {
        clock = clock.wrapping_add(1);
        mixer.tick(&mut hw, black_box(clock));
    });
    report("Mixer::tick (loops only, nothing due)", t, base);

    // A full lane of low-priority one-shots, then a more important one steals.
    let mut shots = Mixer::new([Lane::new(0x00_00ff, Policy::Smart)], 60);
    let low = sound(0, Class::Low, false);
    for _ in 0..8 {
        shots.play(&mut hw, &low, Play::new(500, 500).with_ticks(1000));
    }
    let high = sound(0, Class::High, false);
    let t = ticks(|i| {
        shots.play(
            &mut hw,
            &high,
            Play::new(black_box(2000 + i as i16), 2000).with_ticks(1000),
        );
    });
    report("Mixer::play (Smart, lane full, steals)", t, base);

    // The whole per-emitter update a game does for a held loop: place it, then
    // push the levels to its voice.
    let t = ticks(|i| {
        let e = Emitter::new(black_box(POS[(i & 15) as usize]));
        if let (Some(g), Some(h)) = (
            gains(&equal, &one, ListenerRule::Loudest, &e, &curve),
            handles[(i & 7) as usize],
        ) {
            mixer.update(&mut hw, h, g.left, g.right);
        }
    });
    report("gains + Mixer::update (full emitter update)", t, base);

    tty::println("sfxbench: done");
    loop {}
}
